(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"grammar-sentence-combinations":{"title":"Sentence Combinations","topic":"Grammar & Usage","questions":[{"id":"grammar-sentence-combinations-q0001","version":5,"contentHash":"sha256:a1ce0597b059402a1a3472756573d8ff0c54cf5ccecb94b46d53ff7ac6ed1d4f","question":"Which combines: 'The cat slept. The dog barked.'","choices":["The cat slept the dog barked.","The cat slept, and the dog barked.","The cat slept the dog, barked.","The cat, slept and the dog barked."],"correct":1,"explanation":{"correct":"Answer: The cat slept, and the dog barked. When you join two complete sentences (independent clauses) with a coordinating conjunction like 'and', you must place a comma before the conjunction.","incorrect":[{"choice":"The cat slept the dog barked.","category":"run-on sentence","reason":"This is a run-on sentence because two complete ideas are pushed together without any punctuation or connecting word to separate them."},"",{"choice":"The cat slept the dog, barked.","category":"incorrect comma placement","reason":"Placing a comma after 'dog' does not help connect the two sentences. The comma belongs before the connecting word 'and' to signal the transition between the two thoughts."},{"choice":"The cat, slept and the dog barked.","category":"unnecessary punctuation","reason":"A comma should not separate the subject 'cat' from its verb 'slept'. Only use a comma before 'and' when it is connecting two complete, independent sentences."}]},"studyAid":{"definition":"A compound sentence is formed by joining two independent sentences with a comma and a coordinating conjunction (like and, but, or or).","example":"I like cake, and he likes pie. She wanted to play, but it was raining.","strategyClue":"Check if both parts of the sentence could stand alone as complete ideas. If they can, look for the spot where the first thought ends and the second begins to place your comma and conjunction.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":1,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0002","version":5,"contentHash":"sha256:f442af6a1412db44374ea12e793da63f1eefec07f9028009818653fb0cd4b816","question":"Which combines: 'I like pizza. It is cheesy.' using a subordinating conjunction?","choices":["I like pizza, it is cheesy.","I like pizza because it is cheesy.","I like pizza, and it is cheesy.","I like pizza but it is cheesy."],"correct":1,"explanation":{"correct":"Answer: I like pizza because it is cheesy. 'Because' is a subordinating conjunction, which links a dependent clause to an independent clause, showing a cause-and-effect relationship.","incorrect":[{"choice":"I like pizza, it is cheesy.","category":"comma splice error","reason":"This uses a comma to join two complete sentences. This creates a run-on sentence error known as a comma splice."},"",{"choice":"I like pizza, and it is cheesy.","category":"coordinating conjunction","reason":"The word 'and' is a coordinating conjunction (FANBOYS), not a subordinating conjunction. It joins two equal ideas instead of creating a dependent relationship."},{"choice":"I like pizza but it is cheesy.","category":"coordinating conjunction","reason":"The word 'but' is a coordinating conjunction. It is used to show contrast, not to subordinate the second idea to the first."}]},"studyAid":{"definition":"A subordinating conjunction connects a dependent clause to an independent clause, showing relationships like time, reason, or condition.","example":"I went home because I was tired. I will eat when I am hungry. If it rains, we stay inside.","strategyClue":"Look for the word that explains the 'why' or condition of the action. Compare each connector to the list of subordinating conjunctions (like 'because,' 'although,' or 'if') rather than the coordinating conjunctions (FANBOYS).","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":2,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0003","version":5,"contentHash":"sha256:73db4d22eaec4c7362f6eb67e706614b500879de6fecc50a56fdbd55350c02f7","question":"Which combines: 'She is smart. She is kind.' using a correlative conjunction?","choices":["She is smart and kind.","She is not only smart but also kind.","She is smart, she is kind.","She is smart but kind."],"correct":1,"explanation":{"correct":"Answer: She is not only smart but also kind. The correlative conjunction 'not only... but also' is used to connect two related qualities about the same subject.","incorrect":[{"choice":"She is smart and kind.","category":"simple conjunction","reason":"While this sentence is grammatically correct, it uses the coordinating conjunction 'and' rather than the required correlative conjunction."},"",{"choice":"She is smart, she is kind.","category":"comma splice error","reason":"This choice creates a comma splice because it connects two independent sentences with only a comma. It does not use a correlative conjunction."},{"choice":"She is smart but kind.","category":"incorrect conjunction usage","reason":"The conjunction 'but' is used to show a contrast between two ideas. Since being smart and being kind are not opposites, this is not the right choice."}]},"studyAid":{"definition":"Correlative conjunctions are pairs of words that work together to join equal parts of a sentence, such as 'not only... but also' or 'either... or'.","example":"Correct: Not only is he fast, but he is also strong. Incorrect: Not only he is fast and he is strong.","strategyClue":"Look for the option that uses two linked words to emphasize two positive traits instead of just using one word like 'and' or 'but'.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":3,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0004","version":5,"contentHash":"sha256:94596bed6264e5d064b7c2bed03143ce31074f924a6eda4239ed33a21a0fd946","question":"Which combines: 'The boy ran. He was late.' using a subordinating conjunction?","choices":["The boy ran, and he was late.","The boy ran because he was late.","The boy ran he was late.","The boy ran but he was late."],"correct":1,"explanation":{"correct":"Answer: The boy ran because he was late. 'Because' is a subordinating conjunction, which connects a dependent clause to an independent clause to show a cause-and-effect relationship.","incorrect":[{"choice":"The boy ran, and he was late.","category":"coordinating conjunction","reason":"'And' is a coordinating conjunction (FANBOYS), not a subordinating one. It joins two equal ideas rather than showing a relationship of cause."},"",{"choice":"The boy ran he was late.","category":"run-on sentence","reason":"This is a run-on sentence because two independent clauses are pushed together without any conjunction or punctuation to join them correctly."},{"choice":"The boy ran but he was late.","category":"coordinating conjunction","reason":"'But' is a coordinating conjunction, which is used to show a contrast between two independent thoughts, not to create a subordinating relationship."}]},"studyAid":{"definition":"A subordinating conjunction connects a main idea to a supporting idea that cannot stand alone, explaining the 'why', 'when', or 'where' of the sentence.","example":"I stayed home (because it rained). She will sleep (after the movie ends). We played (until the sun set).","strategyClue":"Look for a joining word that describes the reason or timing behind the action, rather than just connecting two separate facts with 'and', 'but', or 'or'.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":4,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0005","version":5,"contentHash":"sha256:44c564d4251db05b1028662ec8a646c0b070559e7a642effcfe6f3855c05ea86","question":"Which combines: 'It was raining. We stayed inside.' correctly?","choices":["It was raining we stayed inside.","It was raining, so we stayed inside.","It was raining, we stayed inside.","It was raining but we stayed inside."],"correct":1,"explanation":{"correct":"Answer: It was raining, so we stayed inside. The word 'so' acts as a coordinating conjunction to show cause and effect, and it requires a comma before it when connecting two independent sentences.","incorrect":[{"choice":"It was raining we stayed inside.","category":"run-on sentence","reason":"This is a run-on sentence. You need a comma and a coordinating conjunction to join these two complete thoughts together smoothly."},"",{"choice":"It was raining, we stayed inside.","category":"comma splice","reason":"This is a comma splice. A comma alone is not strong enough to connect two complete sentences; you must add a conjunction like 'so' to join them."},{"choice":"It was raining but we stayed inside.","category":"incorrect conjunction","reason":"The word 'but' is used to show contrast or opposition. In this sentence, staying inside is the result of the rain, so 'so' is the correct conjunction to use."}]},"studyAid":{"definition":"A compound sentence joins two simple sentences using a comma and a coordinating conjunction (such as and, but, or, so).","example":"It is cold, so I wore a coat. I like pizza, but I do not like onions.","strategyClue":"Look at the relationship between the two ideas: are they opposites, or is one idea the result of the other? Choose the conjunction that best describes that relationship.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":5,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0006","version":5,"contentHash":"sha256:d1771868851ff166096935723c391c9fbc34ea2cea8bef005d603bd42eaebf53","question":"Which combines: 'The book was long. It was boring.' using a coordinating conjunction that shows contrast?","choices":["The book was long, and it was boring.","The book was long, but it was boring.","The book was long, or it was boring.","The book was long, so it was boring."],"correct":1,"explanation":{"correct":"Answer: The book was long, but it was boring. The coordinating conjunction 'but' is used to show contrast or a difference between two ideas, which fits the relationship between a long book and a boring experience.","incorrect":[{"choice":"The book was long, and it was boring.","category":"incorrect conjunction meaning","reason":"The word 'and' shows addition, not contrast. Use 'and' when you want to connect two similar ideas, not to show a difference."},"",{"choice":"The book was long, or it was boring.","category":"incorrect conjunction meaning","reason":"The word 'or' is used to show a choice between two options. This sentence is stating facts about the book, not offering a choice."},{"choice":"The book was long, so it was boring.","category":"incorrect conjunction meaning","reason":"The word 'so' shows a result or consequence. Being long does not automatically mean a book must be boring, so 'so' does not fit this logic."}]},"studyAid":{"definition":"Coordinating conjunctions (FANBOYS) join words or phrases together. Each one has a specific job: 'but' shows contrast, 'and' shows addition, 'or' shows choices, and 'so' shows results.","example":"I like cake, but I don't like pie. I bought apples and bananas. Do you want juice or water?","strategyClue":"Ask yourself: 'Does the second part of the sentence contradict the first part, or does it add information?' If it contradicts, look for the word that signals a change in direction.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":6,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0007","version":5,"contentHash":"sha256:864219cf3ea5c38ab08874a933658b4244e396e47895e1f8ccd6c66c58eddc65","question":"Which combines: 'I wanted to go. I was too tired.' using a subordinating conjunction?","choices":["I wanted to go, but I was too tired.","Although I wanted to go, I was too tired.","I wanted to go, and I was too tired.","I wanted to go, or I was too tired."],"correct":1,"explanation":{"correct":"Answer: Although I wanted to go, I was too tired. 'Although' is a subordinating conjunction because it introduces a dependent clause and links it to an independent clause.","incorrect":[{"choice":"I wanted to go, but I was too tired.","category":"coordinating conjunction error","reason":"'But' is a coordinating conjunction (FANBOYS), not a subordinating one. This choice connects two equal independent clauses rather than using subordination."},"",{"choice":"I wanted to go, and I was too tired.","category":"coordinating conjunction error","reason":"'And' is a coordinating conjunction used to join items or clauses of equal importance. It does not create the dependent relationship needed for a subordinating conjunction."},{"choice":"I wanted to go, or I was too tired.","category":"coordinating conjunction error","reason":"'Or' is a coordinating conjunction used to show choice. Like the others, it joins two independent thoughts without showing the dependency required by a subordinating conjunction."}]},"studyAid":{"definition":"A subordinating conjunction creates a relationship where one part of the sentence depends on the other. Common examples include because, although, since, and unless.","example":"Because it rained, we stayed inside. / Although I was full, I ate dessert.","strategyClue":"Look for the word that makes one part of the sentence feel incomplete on its own. While coordinating conjunctions (FANBOYS) link equals, subordinating conjunctions introduce a 'subordinate' or dependent thought.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":7,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0008","version":5,"contentHash":"sha256:a08829442bfdc75ba4e1838b1883ed12ba9bac2a25216e09b80fecba6bc5acf5","question":"Which combines: 'You can have cake. You can have ice cream.' using a coordinating conjunction?","choices":["You can have cake, and you can have ice cream.","You can have cake, but you can have ice cream.","You can have cake, so you can have ice cream.","You can have cake, yet you can have ice cream."],"correct":0,"explanation":{"correct":"Answer: You can have cake, and you can have ice cream. 'And' is the correct coordinating conjunction because it shows the addition of two positive options that can both be chosen.","incorrect":["",{"choice":"You can have cake, but you can have ice cream.","category":"conjunction logic error","reason":"'But' is used to show contrast or conflict between two ideas. Since having cake and ice cream are both positive additions, 'but' does not fit the meaning of the sentence."},{"choice":"You can have cake, so you can have ice cream.","category":"conjunction logic error","reason":"'So' is used to show cause and effect. Having cake is not the direct reason why you are allowed to have ice cream, so 'so' is not the best choice here."},{"choice":"You can have cake, yet you can have ice cream.","category":"conjunction logic error","reason":"'Yet' acts similarly to 'but' by showing a surprising contrast. There is no surprise or contradiction here, so 'yet' is not the correct word to connect these two options."}]},"studyAid":{"definition":"Coordinating conjunctions (FANBOYS: for, and, nor, but, or, yet, so) connect words, phrases, or clauses of equal importance. 'And' adds information, while 'but' shows contrast.","example":"I like cats and dogs. I like cats, but I am allergic to them. I can walk or I can run.","strategyClue":"Ask yourself if the two ideas are adding to each other, creating a contrast, or showing a result, then pick the conjunction that matches that relationship.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":8,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0009","version":5,"contentHash":"sha256:944bac5fc42b05ceeae55a055aca99eecb4d63e4eabd80c21b5b755a585d349f","question":"Which combines: 'He studied hard. He passed the test.' using 'because'?","choices":["He studied hard because he passed the test.","He passed the test because he studied hard.","Because he studied hard, and he passed the test.","He studied hard, because he passed the test."],"correct":1,"explanation":{"correct":"Answer: He passed the test because he studied hard. 'Because' is used to show a cause-and-effect relationship; in this sentence, studying hard is the cause that leads to the result of passing the test.","incorrect":[{"choice":"He studied hard because he passed the test.","category":"illogical cause-effect order","reason":"This reverses the logic. Studying hard happens first and causes the result of passing the test, not the other way around."},"",{"choice":"Because he studied hard, and he passed the test.","category":"extra conjunction error","reason":"Including both 'because' and 'and' creates a run-on structure that does not properly link the two independent thoughts as a single cause-and-effect sentence."},{"choice":"He studied hard, because he passed the test.","category":"incorrect comma usage","reason":"You generally do not need a comma before 'because' when it connects two parts of a sentence that explain a direct result."}]},"studyAid":{"definition":"A conjunction like 'because' joins two sentences together to explain why something happened or the reason for an action.","example":"I wore a coat because it was cold. I ate because I was hungry.","strategyClue":"Ask yourself which part is the 'reason' and which part is the 'result.' The sentence should follow the pattern of 'Result' + 'because' + 'Reason'.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":9,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0010","version":5,"contentHash":"sha256:d76678b1696c24f09090e6694a62526730a7f6be07e53b65d2a35e3fa0abff91","question":"Which combines: 'The sun was shining. It was cold.' using contrast?","choices":["The sun was shining, and it was cold.","The sun was shining, but it was cold.","The sun was shining, so it was cold.","The sun was shining, or it was cold."],"correct":1,"explanation":{"correct":"Answer: The sun was shining, but it was cold. The word 'but' is a coordinating conjunction used to join two sentences that show a contrast or surprise, since you might expect it to be warm when the sun is shining.","incorrect":[{"choice":"The sun was shining, and it was cold.","category":"conjunction for addition","reason":"The word 'and' is used to add similar ideas together. Since 'shining' and 'cold' represent a contrast rather than similar information, 'and' does not fit the intended meaning."},"",{"choice":"The sun was shining, so it was cold.","category":"conjunction for consequence","reason":"The word 'so' describes a cause-and-effect relationship. Shining sun usually causes warmth, not cold, so this logic does not make sense."},{"choice":"The sun was shining, or it was cold.","category":"conjunction for options","reason":"The word 'or' is used to present a choice between two things. This sentence does not offer a choice, but rather describes two facts happening at the same time."}]},"studyAid":{"definition":"Coordinating conjunctions connect parts of a sentence. Use 'but' to signal a contrast or an unexpected result between two related ideas.","example":"I wanted to play, but it was raining. The cake looked great, but it tasted salty.","strategyClue":"Ask yourself if the second part of the sentence is what you would expect to happen after the first part; if it is surprising or opposite, choose the conjunction that signals a difference.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":10,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0011","version":5,"contentHash":"sha256:983e16b8ffe822b2cb7a213e7b73515230c2b1c56bdc5b95b82ea57753498880","question":"Which combines: 'She sings. She dances.' using a correlative conjunction?","choices":["She sings and dances.","She not only sings but also dances.","She sings, she dances.","She sings but dances."],"correct":1,"explanation":{"correct":"Answer: She not only sings but also dances. Correlative conjunctions work in pairs to join two parts of a sentence together; 'not only... but also' is a specific pair used to show that both actions happen.","incorrect":[{"choice":"She sings and dances.","category":"coordinating conjunction","reason":"While this is a grammatically correct sentence, it uses the coordinating conjunction 'and' rather than a pair of correlative conjunctions as the question requires."},"",{"choice":"She sings, she dances.","category":"comma splice","reason":"This choice incorrectly joins two complete sentences with only a comma, creating a run-on sentence. It also does not use a correlative conjunction."},{"choice":"She sings but dances.","category":"incorrect conjunction pair","reason":"The word 'but' is used to show a contrast between two ideas. Here, singing and dancing are two things happening together, not opposing each other."}]},"studyAid":{"definition":"Correlative conjunctions are pairs of words that work together to join words or phrases in a sentence. They always travel as a team.","example":"Either/or, Neither/nor, Not only/but also","strategyClue":"Look for the option that uses two linked words instead of just one to connect the ideas of singing and dancing.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":11,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0012","version":5,"contentHash":"sha256:fb3544ce88fd09dde737285f6feaf7ff440656229ada3d20d4cf3c912aa08be5","question":"Which combines: 'The phone rang. I answered it.' using a subordinating conjunction of time?","choices":["When the phone rang, I answered it.","Because the phone rang, I answered it.","Although the phone rang, I answered it.","If the phone rang, I answered it."],"correct":0,"explanation":{"correct":"Answer: When the phone rang, I answered it. 'When' is a subordinating conjunction of time that tells us exactly *when* an action occurred in relation to another action.","incorrect":["",{"choice":"Because the phone rang, I answered it.","category":"causality vs. time","reason":"'Because' is a subordinating conjunction of cause, not time. It explains *why* you answered, rather than *when* it happened."},{"choice":"Although the phone rang, I answered it.","category":"concession vs. time","reason":"'Although' shows a contrast or surprise, not a time relationship. It suggests answering the phone was unexpected given that it rang."},{"choice":"If the phone rang, I answered it.","category":"condition vs. time","reason":"'If' creates a conditional statement about a possibility. It changes the meaning to suggest you only answer the phone *provided that* it rings."}]},"studyAid":{"definition":"A subordinating conjunction connects a dependent clause to an independent clause. Conjunctions of time, such as 'when', 'while', or 'after', specifically tell us the order or duration of events.","example":"After I finish dinner, I will play. (Time). Because I finished dinner, I am full. (Cause). If I finish dinner, I will get dessert. (Condition).","strategyClue":"Ask yourself what the relationship is between the two sentences: are they talking about when something happened, why it happened, or under what conditions? Choose the word that reflects the 'when'.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":12,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0013","version":5,"contentHash":"sha256:739bc00ebd67a8757909fa10befb91d4d364ae9e50bf24bcc309166df8f52505","question":"Which combines: 'He is young. He is wise.' using contrast?","choices":["He is young, and he is wise.","He is young, but he is wise.","He is young, so he is wise.","He is young, or he is wise."],"correct":1,"explanation":{"correct":"Answer: He is young, but he is wise. The word 'but' is a coordinating conjunction used to show contrast or opposition between two ideas.","incorrect":[{"choice":"He is young, and he is wise.","category":"incorrect coordinating conjunction","reason":"'And' is used to show addition, not contrast. Since the sentence asks for a contrast, 'and' does not show how these two qualities are different."},"",{"choice":"He is young, so he is wise.","category":"incorrect causal conjunction","reason":"'So' is used to show cause and effect. Being young does not naturally cause someone to be wise, so 'so' is not the right choice for this sentence."},{"choice":"He is young, or he is wise.","category":"incorrect choice conjunction","reason":"'Or' is used to show a choice between two options. This sentence describes two qualities someone possesses at the same time, not a choice between them."}]},"studyAid":{"definition":"Conjunctions are joining words. 'But' joins ideas that are different or opposite, while 'and' joins ideas that are similar.","example":"I am tired, but I will finish my work. (Contrast); I like pizza, and I like pasta. (Addition)","strategyClue":"Ask yourself if the two ideas are working together or fighting against each other. If the second part of the sentence surprised you or opposes the first part, look for a contrast word.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":13,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0014","version":5,"contentHash":"sha256:e82a0f9be0d28fc10a9f0aa290d5ef9436921a0434ae66187daa8f48d191c9de","question":"Which combines: 'You study. You will pass.' using a subordinating conjunction of condition?","choices":["You study, and you will pass.","If you study, you will pass.","Because you study, you will pass.","Although you study, you will pass."],"correct":1,"explanation":{"correct":"Answer: If you study, you will pass. The word 'if' is a subordinating conjunction of condition, meaning it establishes a requirement for an action to happen.","incorrect":[{"choice":"You study, and you will pass.","category":"coordinating conjunction","reason":"This uses 'and,' which is a coordinating conjunction used to join equal ideas, not to show a conditional relationship."},"",{"choice":"Because you study, you will pass.","category":"conjunction of cause","reason":"'Because' expresses a reason or cause for an action rather than a condition that must be met for something else to happen."},{"choice":"Although you study, you will pass.","category":"conjunction of concession","reason":"'Although' shows a contrast or exception, rather than setting up a condition required for the outcome."}]},"studyAid":{"definition":"A subordinating conjunction of condition introduces a requirement that must happen for the main part of the sentence to occur.","example":"If it rains, we stay inside. Unless you hurry, you will be late.","strategyClue":"Ask yourself if the second part of the sentence depends on the first part happening. Look for the word that implies a requirement rather than a reason, contrast, or simple addition.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":14,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0015","version":5,"contentHash":"sha256:112422079d3318fe1fe93718be0e0b24c316abc1d35957aa8cbaa2ba69369d87","question":"Which combines: 'I like tea. I like coffee.' using a correlative conjunction?","choices":["I like tea and coffee.","I like both tea and coffee.","I like tea, I like coffee.","I like tea but coffee."],"correct":1,"explanation":{"correct":"Answer: I like both tea and coffee. The correlative conjunction 'both... and' is used to connect two items, showing that you enjoy each of them.","incorrect":[{"choice":"I like tea and coffee.","category":"simple conjunction","reason":"While this is grammatically correct, it uses a simple conjunction ('and') rather than a correlative conjunction pair."},"",{"choice":"I like tea, I like coffee.","category":"comma splice error","reason":"This is a run-on sentence because two independent clauses are joined by only a comma instead of a conjunction or a semicolon."},{"choice":"I like tea but coffee.","category":"incorrect conjunction usage","reason":"The word 'but' indicates contrast, which doesn't make sense here since you like both drinks. Use a correlative pair that shows addition."}]},"studyAid":{"definition":"Correlative conjunctions are pairs of words used to join two equal parts of a sentence, such as 'both... and' or 'either... or'.","example":"Correct: I want both pizza and pasta. Incorrect: I want both pizza, pasta.","strategyClue":"Look for the sentence option that includes a pair of words specifically designed to work together as a team to link the two objects.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":15,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0016","version":5,"contentHash":"sha256:4bb70ac48d9d1febfeb78d5dda0ca634491462ff4ea68ebca3a45dc646a42794","question":"Combine the two sentences to make one sentence: Joan Schultze is a doctor. She lives in Oregon.","choices":["Joan Schultze is a doctor who lives in Oregon.","Joan Schultze is a doctor.","She lives in Oregon.","Joan Schultze is a doctor she lives in Oregon."],"correct":0,"explanation":{"correct":"Answer: Joan Schultze is a doctor who lives in Oregon. Using the relative pronoun 'who' connects two ideas about the same person, turning two separate sentences into one smooth, complex sentence.","incorrect":["",{"choice":"Joan Schultze is a doctor.","category":"incomplete sentence combination","reason":"This option keeps only the first sentence and ignores the information about Oregon. To combine sentences, you must include the details from both."},{"choice":"She lives in Oregon.","category":"incomplete sentence combination","reason":"This option keeps only the second sentence and loses the information about the subject's profession. A good combination must link both facts."},{"choice":"Joan Schultze is a doctor she lives in Oregon.","category":"run-on sentence error","reason":"This is a run-on sentence because two independent clauses are joined without any connecting word or punctuation. You need a word like 'who' or a semicolon to bridge them correctly."}]},"studyAid":{"definition":"You can combine two sentences into one by using words like 'who', 'which', 'because', or 'and' to show how the ideas are related.","example":"Original: The dog barked. He was hungry. Combined: The dog who was hungry barked.","strategyClue":"Look for a word that appears in both sentences, such as a name or a pronoun. Use a joining word to replace the second subject so the two thoughts flow together as one.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":16,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0017","version":5,"contentHash":"sha256:ffee4904dbd69a25afad8e4dcf76b75899080d25ce9f69421be4c16a8ed3e72b","question":"Combine the two sentences to make one sentence: Our dog is seven years old. Her name is Molly.","choices":["Our dog, Molly, is seven years old.","Our dog is seven years old.","Her name is Molly.","Our dog is seven years old her name is Molly."],"correct":0,"explanation":{"correct":"Answer: Our dog, Molly, is seven years old. Using an appositive—a noun that renames another noun—allows you to combine related ideas smoothly. By placing the name 'Molly' between commas, you connect the name to the subject, 'Our dog,' creating one fluid sentence.","incorrect":["",{"choice":"Our dog is seven years old.","category":"missing information","reason":"This choice ignores the second sentence entirely. Combining means you need to include the essential information from both original sentences."},{"choice":"Her name is Molly.","category":"missing information","reason":"This choice leaves out the information about the dog's age. A combined sentence should tell the reader both facts at once."},{"choice":"Our dog is seven years old her name is Molly.","category":"run-on sentence","reason":"This is a run-on sentence because it forces two complete thoughts together without any punctuation or connecting words to show how they relate."}]},"studyAid":{"definition":"You can combine two sentences into one by using an appositive, which is a noun phrase that renames the subject and is set off by commas.","example":"My brother is tall. My brother, John, is tall. My pet is a cat. My pet, Whiskers, is a cat.","strategyClue":"Look for a noun in the second sentence that describes the subject of the first sentence, then try to tuck that noun into the first sentence using commas.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":17,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0018","version":5,"contentHash":"sha256:9483b565b0525c7166b3d66e4f6a543b38a4ba6b162b61164600aa9e92f0ffb9","question":"Combine the two sentences to make one sentence: My uncle is coming to visit us. He will be here Tuesday.","choices":["My uncle is coming to visit us this Tuesday.","My uncle is coming to visit us.","He will be here Tuesday.","My uncle is coming to visit us he will be here Tuesday."],"correct":0,"explanation":{"correct":"Answer: My uncle is coming to visit us this Tuesday. Combining these sentences into one creates a clearer, more efficient flow. By using 'this Tuesday' as a time modifier, we remove the need for a second, separate sentence.","incorrect":["",{"choice":"My uncle is coming to visit us.","category":"incomplete information","reason":"This option leaves out the important detail about when your uncle is arriving. A good combined sentence includes all the information from the original two sentences."},{"choice":"He will be here Tuesday.","category":"missing information","reason":"This option leaves out the identity of who is coming. Always make sure that a combined sentence clearly describes who is the subject of the action."},{"choice":"My uncle is coming to visit us he will be here Tuesday.","category":"run-on sentence","reason":"This combines the two ideas without using any punctuation or connecting words between 'us' and 'he'. This creates a run-on sentence, which is hard to read."}]},"studyAid":{"definition":"You can combine two sentences into one by using words that show time, place, or connection, or by using conjunctions like 'and' or 'because'.","example":"I like cake. I like cookies. -> I like cake and cookies. / The dog barked. He was hungry. -> The hungry dog barked.","strategyClue":"Look at both sentences to identify the shared subject or information. Try to move the time or detail from the second sentence into the first sentence to link the ideas together.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":18,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0019","version":5,"contentHash":"sha256:d0680b096a52cb5c6285105facc08c9f03a49d0b0324ca5c958baf3fe3873a49","question":"Combine the two sentences to make one sentence: Cinderella swept the steps. Cinderella washed the floor.","choices":["Combine the two sentences to make one sentence: Cinderella swept the steps.","Cinderella swept the steps and washed the floor.","Cinderella washed the floor.","Cinderella swept the steps but washed the floor."],"correct":1,"explanation":{"correct":"Answer: Cinderella swept the steps and washed the floor. By using the conjunction 'and', you can combine two sentences that describe related actions performed by the same subject into one smooth sentence.","incorrect":[{"choice":"Combine the two sentences to make one sentence: Cinderella swept the steps.","category":"incomplete sentence combination","reason":"This choice ignores the second action entirely and keeps the instruction text, failing to combine the two ideas into a single sentence."},"",{"choice":"Cinderella washed the floor.","category":"incomplete sentence combination","reason":"This choice omits the first action, 'swept the steps,' losing part of the information provided in the original sentences."},{"choice":"Cinderella swept the steps but washed the floor.","category":"misused conjunction","reason":"The word 'but' is used to show a contradiction or surprise. Since these are two normal chores performed together, 'and' is the better conjunction to join them."}]},"studyAid":{"definition":"You can use conjunctions like 'and' to join two short sentences together when they share the same subject and the ideas are similar.","example":"He ate the cake. He drank the milk. -> He ate the cake and drank the milk.","strategyClue":"Identify the repeated subject, keep it once, and look for a conjunction that links two similar actions without changing the meaning of either part.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":19,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0020","version":5,"contentHash":"sha256:e5afa84aa597d36778cdfb22b39c0e795d18c872f0d902fc906baf21b333e7ed","question":"Combine the two sentences to make one sentence: I am scared of mice. I am scared of spiders, too.","choices":["I am scared of mice and spiders.","I am scared of mice but spiders.","I am scared of spiders, too.","Combine the two sentences to make one sentence: I am scared of mice."],"correct":0,"explanation":{"correct":"Answer: I am scared of mice and spiders. Using 'and' allows you to combine two similar ideas into one list, removing the need for a second 'I am scared of'.","incorrect":["",{"choice":"I am scared of mice but spiders.","category":"incorrect conjunction usage","reason":"The word 'but' is used for contrast, not for adding items to a list. Since you are scared of both, 'and' is the correct connector."},{"choice":"I am scared of spiders, too.","category":"incomplete information","reason":"This choice ignores the first sentence. To combine the sentences, you must include both subjects: mice and spiders."},{"choice":"Combine the two sentences to make one sentence: I am scared of mice.","category":"instruction error","reason":"This is a repetition of the prompt's instructions rather than an actual answer. It also fails to include the information about the spiders."}]},"studyAid":{"definition":"A compound sentence or list uses a coordinating conjunction like 'and' to join two similar nouns or ideas together.","example":"I like cats and dogs. (Not: I like cats but dogs.) I enjoy reading and drawing.","strategyClue":"Identify the repeated parts in both sentences and cross them out; then, use a connector word to link the remaining unique items together.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":20,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0021","version":4,"contentHash":"sha256:c8fd2924aff1407784d8f1ab0ce95ddad20a363daadb2c36febaa1dd205d7b5c","question":"He wants a baseball glove. He needs it for the game.","choices":["He needs it for the game.","He wants a baseball glove because he needs it for the game.","He wants a baseball glove so he needs it for the game.","He wants a baseball glove."],"correct":1,"explanation":{"correct":"Answer: He wants a baseball glove because he needs it for the game. The word 'because' is a subordinating conjunction that shows the reason or cause for wanting the glove.","incorrect":[{"choice":"He needs it for the game.","category":"sentence fragment","reason":"This is only the second part of the original pair. It misses the reason for the action and ignores the request to combine both sentences."},"",{"choice":"He wants a baseball glove so he needs it for the game.","category":"illogical conjunction","reason":"Using 'so' suggests that wanting a glove is the reason he needs it. The logic is backwards; he needs the glove because of the game."},{"choice":"He wants a baseball glove.","category":"incomplete information","reason":"This choice only includes the first sentence, leaving out the important information about why he needs the glove."}]},"studyAid":{"definition":"A conjunction is a connecting word used to join two sentences together. Some conjunctions show cause and effect, while others show contrast.","example":"I ate because I was hungry. I finished my homework so I could play. It was raining, but we went outside.","strategyClue":"Ask yourself which part of the sentence is the 'reason' and which part is the 'result.' Choose the connecting word that best fits the relationship between those two ideas.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":21,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0022","version":4,"contentHash":"sha256:7184c68212dc9506f38729bc10e5b33290fe73707086990b60136bb6a275f5c7","question":"Jerrod has three sisters. Jerrod is the youngest.","choices":["Jerrod is the youngest of three sisters.","Jerrod has three sisters.","Jerrod is the youngest.","Jerrod has three sisters jerrod is the youngest."],"correct":0,"explanation":{"correct":"Answer: Jerrod is the youngest of three sisters. This choice correctly uses a prepositional phrase to combine two simple sentences into one fluid, complete sentence.","incorrect":["",{"choice":"Jerrod has three sisters.","category":"Incomplete information","reason":"This sentence only tells us about the sisters and misses the key information that Jerrod is the youngest."},{"choice":"Jerrod is the youngest.","category":"Incomplete information","reason":"This sentence misses the context about Jerrod having three sisters, which is necessary to understand why he is the youngest."},{"choice":"Jerrod has three sisters jerrod is the youngest.","category":"Run-on sentence","reason":"This is a run-on sentence because two complete thoughts are pushed together without any punctuation or connecting words to join them."}]},"studyAid":{"definition":"A sentence should express a complete thought. You can combine related short sentences using words like 'and', 'but', or by creating a phrase that connects the ideas.","example":"Simple: She is tired. She studied. Combined: She is tired because she studied.","strategyClue":"Look for the option that keeps all the facts together in one smooth flow instead of leaving ideas separated or disconnected.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":22,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0023","version":4,"contentHash":"sha256:26034e5ede00eaa266ed7678d0d2b09165379ddcf5c36477cd1908979827d601","question":"We took a walk around the block. We walked for an hour.","choices":["We took a walk around the block for an hour.","We took a walk around the block.","We walked for an hour.","We took a walk around the block we walked for an hour."],"correct":0,"explanation":{"correct":"Answer: We took a walk around the block for an hour. This version uses a prepositional phrase to combine two related ideas into a single, smooth sentence, avoiding repetition and choppiness.","incorrect":["",{"choice":"We took a walk around the block.","category":"incomplete information","reason":"This choice is missing the second part of the information provided in the prompt, leaving out how long the walk lasted."},{"choice":"We walked for an hour.","category":"incomplete information","reason":"This choice omits the important detail about where you walked, making the sentence less descriptive than the original combined version."},{"choice":"We took a walk around the block we walked for an hour.","category":"run-on sentence","reason":"This choice places two independent sentences together without any punctuation or connecting word, creating a run-on sentence."}]},"studyAid":{"definition":"A sentence is a complete thought. You can combine short, related sentences into one by using words like 'for,' 'and,' or 'because' to make your writing flow better.","example":"Choppy: I went to the park. I played on the swings. Combined: I went to the park to play on the swings.","strategyClue":"Look for words that appear in both sentences and try to remove the repetition. Ask yourself if the two ideas can be joined by a bridge word to create one clear sentence.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":23,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0024","version":4,"contentHash":"sha256:ea6c28116537f10952e7ceb388edfd01c91622e71fa3d4c5cf14fd3680a54a0f","question":"Do you know the time? Do you wear a watch?","choices":["Do you know the time, or do you wear a watch?","Do you know the time?","Do you wear a watch?","Do you know the time do you wear a watch?"],"correct":0,"explanation":{"correct":"Answer: Do you know the time, or do you wear a watch? A comma followed by a coordinating conjunction (like 'or') is used to connect two complete, related questions into a single sentence.","incorrect":["",{"choice":"Do you know the time?","category":"incomplete sentence structure","reason":"This only includes half of the original two sentences. To combine them correctly, you must include both thoughts joined by a conjunction."},{"choice":"Do you wear a watch?","category":"incomplete sentence structure","reason":"This option leaves out the first question about the time. A correct combination must retain both parts of the original prompt."},{"choice":"Do you know the time do you wear a watch?","category":"missing punctuation/conjunction","reason":"This is a run-on sentence. You need a comma and a conjunction like 'or' to bridge the gap between two separate question clauses."}]},"studyAid":{"definition":"A compound sentence joins two complete thoughts together using a comma and a coordinating conjunction like 'and', 'but', or 'or'.","example":"I like cats, or I like dogs. She ran fast, but she missed the bus.","strategyClue":"Look for two separate question phrases that can stand on their own. Decide if you are offering a choice, and use the correct joining word and a comma before it to link them smoothly.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":24,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0025","version":4,"contentHash":"sha256:d613ee25572c6fa6e9b6dc9ac227377a5bf8ba75b9c7dfb16170b67efaaf8d9a","question":"The ornaments were pretty. There were many of them.","choices":["There were many pretty ornaments.","The ornaments were pretty.","There were many of them.","The ornaments were pretty there were many of them."],"correct":0,"explanation":{"correct":"Answer: There were many pretty ornaments. This choice correctly combines the two short sentences into one by moving the adjective 'pretty' to describe the noun 'ornaments' directly.","incorrect":["",{"choice":"The ornaments were pretty.","category":"incomplete information","reason":"This sentence describes the ornaments but leaves out the second part of the original message, which tells us that there were many of them."},{"choice":"There were many of them.","category":"missing descriptive detail","reason":"This choice mentions the quantity, but it loses the important detail that the ornaments were 'pretty'."},{"choice":"The ornaments were pretty there were many of them.","category":"run-on sentence","reason":"This is a run-on sentence because two complete ideas are pushed together without any punctuation or joining word to separate them."}]},"studyAid":{"definition":"You can combine short, related sentences by turning an adjective from one sentence into a modifier for the noun in the other.","example":"The dog was small. The dog was fluffy. -> The small, fluffy dog.","strategyClue":"Look for adjectives in the first sentence and try placing them directly in front of the noun they describe in the second sentence.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":25,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0026","version":4,"contentHash":"sha256:f839209ed8e6c75520166f5fc4582e87eb9a59e511092bfffcbbe189d98256fe","question":"We are going to Sam's house. We will leave at 4:30.","choices":["We will leave at 4:30 to go to Sam's house.","We are going to Sam's house.","We will leave at 4:30.","We are going to Sam's house we will leave at 4:30."],"correct":0,"explanation":{"correct":"Answer: We will leave at 4:30 to go to Sam's house. This choice correctly joins the two simple sentences into one complex sentence using an infinitive phrase, avoiding the errors of fragments or run-on sentences.","incorrect":["",{"choice":"We are going to Sam's house.","category":"incomplete information","reason":"This choice ignores the second piece of information about the time. A good combined sentence should include all the ideas from the original prompt."},{"choice":"We will leave at 4:30.","category":"incomplete information","reason":"This choice misses the destination mentioned in the first sentence. To combine these ideas properly, you must represent the full meaning of both sentences."},{"choice":"We are going to Sam's house we will leave at 4:30.","category":"run-on sentence","reason":"This is a run-on sentence because two complete thoughts are pushed together without any punctuation or connecting words to bridge them."}]},"studyAid":{"definition":"A sentence must express a complete thought. When combining two short sentences, you can use connecting words or phrases to link them into one smooth flow.","example":"Original: The dog ran. He barked. Combined: The dog ran and barked.","strategyClue":"Read each option aloud. Check if the sentence expresses both main ideas clearly and if it sounds like one smooth, complete thought rather than two separate sentences stuck together.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":26,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0027","version":4,"contentHash":"sha256:265a2bc1a187c26fe91ce60ff73a4f5cfb571886cdd2bad430e752adefe4e4bf","question":"Sara knows her addition facts. She knows her subtraction facts, too.","choices":["Sara knows her addition but subtraction facts.","Sara knows her addition facts.","She knows her subtraction facts, too.","Sara knows her addition and subtraction facts."],"correct":3,"explanation":{"correct":"Answer: Sara knows her addition and subtraction facts. Using the conjunction 'and' allows you to combine two related sentences into one smooth sentence by joining the objects of the verb.","incorrect":[{"choice":"Sara knows her addition but subtraction facts.","category":"improper conjunction","reason":"The word 'but' is used to show contrast or a difference. Since addition and subtraction are both math facts that Sara knows, 'and' is the correct connector."},{"choice":"Sara knows her addition facts.","category":"incomplete information","reason":"This sentence only mentions one type of math fact. It leaves out the important information about subtraction that was provided in the original text."},{"choice":"She knows her subtraction facts, too.","category":"incomplete information","reason":"This sentence fails to combine the ideas. It only mentions the subtraction facts and misses the part about her addition knowledge."},""]},"studyAid":{"definition":"A compound sentence or phrase uses coordinating conjunctions like 'and' or 'but' to link two related ideas together into a single, clearer sentence.","example":"I like cats and dogs. (Correct) vs. I like cats. I like dogs. (Correct, but wordy). I like cats but dogs. (Incorrect)","strategyClue":"Look for repeated words or actions in both sentences. Identify the parts that are different and use a connecting word to group those different items together after the shared action.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":27,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0028","version":4,"contentHash":"sha256:9ba8ef83212c9acce4bc8a0a12b8059bad5e96fce7b55b9033f3e394c9a79a20","question":"Jason is five years old. Henry is six years old.","choices":["Jason is five years old.","Henry is six years old.","Jason is five years old, but Henry is six years old.","Jason is five years old, and Henry is six years old."],"correct":3,"explanation":{"correct":"Answer: Jason is five years old, and Henry is six years old. The conjunction 'and' is used to connect two related sentences that share a similar idea, creating a compound sentence.","incorrect":[{"choice":"Jason is five years old.","category":"incomplete sentence combination","reason":"This choice only includes the first part of the information. To combine the thoughts, you need to include both Jason's and Henry's ages."},{"choice":"Henry is six years old.","category":"incomplete sentence combination","reason":"This choice only includes the second part of the information. To link the ideas together, you need to mention both subjects."},{"choice":"Jason is five years old, but Henry is six years old.","category":"incorrect conjunction choice","reason":"The word 'but' is used to show contrast or a difference. Since these two facts are just listing ages, 'and' is the better choice to join them."},""]},"studyAid":{"definition":"A compound sentence joins two simple sentences together using a comma and a coordinating conjunction like 'and', 'but', or 'or'.","example":"I like cake, and I like pie. It is raining, but we are still going to play.","strategyClue":"Look at the relationship between the two facts. If they are just listing related information, pick the word that adds them together; if they are opposites, pick the word that shows contrast.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":28,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0029","version":4,"contentHash":"sha256:795c70ec1a7dac9854f8764f6e6ab75ada523dc0508fe4e98e1a4b71e47fdb7a","question":"I will order pepperoni pizza. I'll order a salad first.","choices":["I will order pepperoni pizza, but I'll order a salad first.","I will order pepperoni pizza.","I'll order a salad first.","I will order pepperoni pizza i'll order a salad first."],"correct":0,"explanation":{"correct":"Answer: I will order pepperoni pizza, but I'll order a salad first. When joining two complete sentences (independent clauses) with a coordinating conjunction like 'but,' you must use a comma before the conjunction to separate the two ideas correctly.","incorrect":["",{"choice":"I will order pepperoni pizza.","category":"fragmented sentence","reason":"This is only the first half of the thought. The prompt asks you to combine both sentences, and choosing only one leaves out the important information about the salad."},{"choice":"I'll order a salad first.","category":"fragmented sentence","reason":"This choice only includes the second part of the idea. To show the relationship between ordering pizza and the salad, you must include both parts in one sentence."},{"choice":"I will order pepperoni pizza i'll order a salad first.","category":"run-on sentence","reason":"This creates a run-on sentence. When joining two complete sentences, you need a comma and a conjunction (like 'but') to bridge them properly."}]},"studyAid":{"definition":"A compound sentence is formed by joining two independent clauses with a comma and a coordinating conjunction (for, and, nor, but, or, yet, so).","example":"I like cats, but I am allergic. She studied hard, so she passed the test.","strategyClue":"Identify the two complete sentences first, then look for the version that connects them using a comma combined with a word that shows a contrast between the two actions.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":29,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0030","version":4,"contentHash":"sha256:7d94de9db4ba5e5c4813c8b5668c814734f53f19ae372fa7bcf4854619945e40","question":"Our family has two girls and a boy. The boy's name is Stephen.","choices":["Our family has two girls but a boy named Stephen.","Our family has two girls and a boy.","Our family has two girls and a boy named Stephen.","The boy's name is Stephen."],"correct":2,"explanation":{"correct":"Answer: Our family has two girls and a boy named Stephen. Combining these two sentences using a participle phrase creates a more fluid, cohesive sentence that connects the boy directly to his name.","incorrect":[{"choice":"Our family has two girls but a boy named Stephen.","category":"incorrect conjunction usage","reason":"The word 'but' is used to show a contrast between two ideas. Since having a boy is not the opposite of having girls, use 'and' instead."},{"choice":"Our family has two girls and a boy.","category":"incomplete information","reason":"While this sentence is grammatically correct, it leaves out the important detail that the boy's name is Stephen, which was provided in the original text."},"",{"choice":"The boy's name is Stephen.","category":"sentence fragmenting","reason":"This is only half of the required information. Combining the sentences provides a complete picture of the family members mentioned."}]},"studyAid":{"definition":"You can combine two related sentences into one by using a phrase or conjunction to make your writing flow better.","example":"I have a dog. His name is Rex. -> I have a dog named Rex. / She likes apples. She likes grapes. -> She likes apples and grapes.","strategyClue":"Look for shared subjects or repeating ideas between two sentences. Ask yourself if you can remove the repetitive words and join the sentences with a single descriptive phrase.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":30,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0031","version":5,"contentHash":"sha256:17e58b8b6287291e9b6da1dca2f2d5c817a855b45d922da0e523b0c5460718c9","question":"Combine these two sentences into one sentence: Hobie has a cat. The cat's name is Elvis.","choices":["Hobie has a cat named Elvis.","Hobie has a cat.","The cat's name is Elvis.","Hobie has a cat the cat's name is Elvis."],"correct":0,"explanation":{"correct":"Answer: Hobie has a cat named Elvis. By replacing 'The cat's name is' with the single word 'named,' you combine the two related ideas into one smooth sentence without unnecessary repetition.","incorrect":["",{"choice":"Hobie has a cat.","category":"Incomplete information","reason":"While this is a grammatically correct sentence, it leaves out the second piece of information about the cat's name."},{"choice":"The cat's name is Elvis.","category":"Incomplete information","reason":"This only tells us the cat's name but fails to include the original subject, Hobie, or his relationship to the cat."},{"choice":"Hobie has a cat the cat's name is Elvis.","category":"Run-on sentence","reason":"This is a run-on sentence because it forces two complete sentences together without any punctuation or connecting words to show how they are linked."}]},"studyAid":{"definition":"You can combine sentences by turning the second sentence into a phrase that describes a noun in the first sentence.","example":"Correct: The dog has a blue collar. The dog is mine. -> The dog with the blue collar is mine.","strategyClue":"Look for words that repeat in both sentences and try to find a way to replace the second sentence with a descriptive phrase that attaches directly to the common noun.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":31,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0032","version":5,"contentHash":"sha256:9b7a5b038fc75c85f0ca78cac627976f11ec7f2e634dd045adc4344cb647847f","question":"Combine the two sentences to make one sentence: Have you read The Chocolate Touch? It's a great book.","choices":["Have you read the great book, The Chocolate Touch?","Have you read The Chocolate Touch?","It's a great book.","Have you read The Chocolate Touch it's a great book."],"correct":0,"explanation":{"correct":"Answer: Have you read the great book, The Chocolate Touch?. Combining sentences often requires using descriptive words from one sentence as modifiers in another, while adding a comma to connect the title of the book to its description.","incorrect":["",{"choice":"Have you read The Chocolate Touch?","category":"missing information","reason":"This choice ignores the second sentence entirely. To combine sentences, you need to include the important information from both parts."},{"choice":"It's a great book.","category":"missing original subject","reason":"This choice leaves out the first sentence. You must include the question about reading the book to keep the meaning of the original sentences."},{"choice":"Have you read The Chocolate Touch it's a great book.","category":"run-on sentence","reason":"This choice pushes two independent thoughts together without any punctuation or connecting words, which creates a run-on sentence."}]},"studyAid":{"definition":"You can combine sentences by turning one idea into a descriptive phrase that explains a noun in the other sentence.","example":"Original: She has a dog. It is fluffy. Combined: She has a fluffy dog.","strategyClue":"Look for a noun that is described in the second sentence, then move that description to appear directly before or after that noun in the first sentence.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":32,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0033","version":5,"contentHash":"sha256:3e4adddb2d66e84481e8a5ffc990142661a1245064941e905fc5c9bd404079ab","question":"Combine the two sentences to make one sentence: The timer went off after five minutes. The egg was cooked.","choices":["The egg was cooked.","The timer went off after five minutes, but the egg was cooked.","The timer went off after five minutes, and the egg was cooked.","Combine the two sentences to make one sentence: The timer went off after five minutes."],"correct":2,"explanation":{"correct":"Answer: The timer went off after five minutes, and the egg was cooked. Using the coordinating conjunction 'and' correctly joins two related ideas that happen in sequence or together, creating a compound sentence.","incorrect":[{"choice":"The egg was cooked.","category":"missing information","reason":"This option leaves out the first half of the sentence, causing the reader to miss the important detail about the timer."},{"choice":"The timer went off after five minutes, but the egg was cooked.","category":"incorrect conjunction usage","reason":"The word 'but' is used to show a contrast or surprise. Since these two events work well together, 'and' is a better choice than 'but'."},"",{"choice":"Combine the two sentences to make one sentence: The timer went off after five minutes.","category":"failure to combine","reason":"This is just repeating part of the instructions rather than providing a combined sentence."}]},"studyAid":{"definition":"A compound sentence joins two complete thoughts together using a comma and a coordinating conjunction like 'and', 'but', or 'or'.","example":"I like cats, and I like dogs. I wanted to go outside, but it was raining.","strategyClue":"Look for the relationship between the two ideas: do they support each other (use 'and') or do they contradict each other (use 'but')?","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":33,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0034","version":5,"contentHash":"sha256:b7666857b2a77e1ae0f8553022c372e61d725fc1c5cacaa5c17158ce1a3a201a","question":"Combine the two sentences to make one sentence: I have a dalmatian. Her name is Lady.","choices":["I have a dalmatian named Lady.","I have a dalmatian.","Her name is Lady.","I have a dalmatian her name is Lady."],"correct":0,"explanation":{"correct":"Answer: I have a dalmatian named Lady. This version effectively combines the two thoughts by using a participle phrase to describe the noun 'dalmatian' without needing a separate sentence or a comma splice.","incorrect":["",{"choice":"I have a dalmatian.","category":"missing key information","reason":"This choice omits the second sentence entirely, so the reader never learns the name of the dog."},{"choice":"Her name is Lady.","category":"missing key information","reason":"This choice ignores the first sentence, so the reader does not know what animal you are talking about."},{"choice":"I have a dalmatian her name is Lady.","category":"run-on sentence","reason":"This is a run-on sentence because two independent clauses are joined together without any punctuation or connecting words to separate them."}]},"studyAid":{"definition":"You can combine sentences by using words like 'who,' 'which,' or a participle to describe a noun, turning two separate sentences into one smooth flow.","example":"I have a car. It is blue. -> I have a blue car. / She has a cat. Its name is Mittens. -> She has a cat named Mittens.","strategyClue":"Look for the noun that appears in both sentences (or refers to the same subject). Try to move the description of that noun directly next to it to eliminate the need for a second sentence.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":34,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0035","version":5,"contentHash":"sha256:d46457bdbbe6d8c813dc470b830a34d74a6a2c767c8c3db2992dc87ca62d08ff","question":"Combine the two sentences to make one sentence: Jordan sits in the front of the class. He needs glasses.","choices":["Jordan sits in the front of the class because he needs glasses.","Combine the two sentences to make one sentence: Jordan sits in the front of the class.","Jordan sits in the front of the class so he needs glasses.","He needs glasses."],"correct":0,"explanation":{"correct":"Answer: Jordan sits in the front of the class because he needs glasses. This option uses the subordinating conjunction 'because' to logically explain the relationship between the two facts: sitting in the front is a result of needing glasses.","incorrect":["",{"choice":"Combine the two sentences to make one sentence: Jordan sits in the front of the class.","category":"incomplete information","reason":"This choice ignores the second sentence entirely. A good combination should include the main ideas from both original sentences."},{"choice":"Jordan sits in the front of the class so he needs glasses.","category":"illogical conjunction","reason":"Using 'so' suggests that sitting in the front is the cause that makes him need glasses, which is backward! The glasses are the reason he sits in the front."},{"choice":"He needs glasses.","category":"missing information","reason":"This choice leaves out the important detail about Jordan sitting in the front. Make sure your combined sentence includes the complete context of the original two sentences."}]},"studyAid":{"definition":"Conjunctions like 'because', 'although', or 'since' help connect two ideas by showing how they are related to each other.","example":"I ate lunch because I was hungry. I wore a coat because it was cold outside.","strategyClue":"Ask yourself which part of the sentence describes the 'cause' and which part describes the 'effect'. Pick the connecting word that makes the cause-and-effect relationship clear.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":35,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0036","version":5,"contentHash":"sha256:558be53b479ddee2fa0b9e2353d44bf7dceb0c6f6c4f26942c86d2e5a3df509c","question":"Combine the two sentences to make one sentence: Grandma will call this Sunday. She will call at 6:30 p.m.","choices":["Combine the two sentences to make one sentence: Grandma will call this Sunday.","Grandma will call this Sunday at 6:30 p.","She will call at 6:30 p.","Grbutma will call this Sunday at 6:30 p."],"correct":1,"explanation":{"correct":"Answer: Grandma will call this Sunday at 6:30 p.m. To combine two sentences effectively, look for the repeated subject and verb, then remove the extra words to create one smooth, flowing sentence.","incorrect":[{"choice":"Combine the two sentences to make one sentence: Grandma will call this Sunday.","category":"Incomplete sentence combination","reason":"This choice only includes the first sentence and ignores the important time information about when Grandma is calling."},"",{"choice":"She will call at 6:30 p.","category":"Missing subject information","reason":"This choice leaves out 'Grandma,' which makes it unclear who 'She' refers to when the sentences are combined."},{"choice":"Grbutma will call this Sunday at 6:30 p.","category":"Spelling error","reason":"This option contains a typo in the name 'Grandma'. Always double-check your spelling when you combine or rewrite sentences."}]},"studyAid":{"definition":"You can combine two sentences into one by removing repeating words and using a connecting phrase to join the ideas together.","example":"Original: The dog ran. The dog barked. Combined: The dog ran and barked.","strategyClue":"Identify the extra words that repeat the same information in both sentences. Keep the necessary details and use a preposition like 'at' or a conjunction like 'and' to bridge the two parts into one coherent thought.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":36,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0037","version":5,"contentHash":"sha256:2688290137640ea6e481a744e5d70148873e493e81fbc13ab53e8c892ab40770","question":"Combine the two sentences to make one sentence: I like vanilla ice cream best. I don't like strawberry.","choices":["I like vanilla ice cream best, but I don't like strawberry.","I like vanilla ice cream best.","I don't like strawberry.","I like vanilla ice cream best i don't like strawberry."],"correct":0,"explanation":{"correct":"Answer: I like vanilla ice cream best, but I don't like strawberry. We use the coordinating conjunction 'but' to join two complete sentences that express contrasting or opposite ideas.","incorrect":["",{"choice":"I like vanilla ice cream best.","category":"Incomplete information","reason":"This choice ignores the second part of the information provided, leaving out the fact that you do not like strawberry."},{"choice":"I don't like strawberry.","category":"Incomplete information","reason":"This choice misses the first part of the sentence, which tells us your favorite flavor."},{"choice":"I like vanilla ice cream best i don't like strawberry.","category":"Run-on sentence","reason":"This creates a run-on sentence by joining two complete thoughts without any punctuation or a connecting word."}]},"studyAid":{"definition":"A compound sentence joins two complete thoughts together using a comma and a coordinating conjunction like 'and', 'but', or 'or'.","example":"Correct: I love dogs, but I am allergic to cats. Incorrect: I love dogs I am allergic to cats.","strategyClue":"Identify the two separate ideas in the prompt. Since one sentence likes a flavor and the other dislikes a flavor, decide if they are showing agreement or a contrast to pick the right joining word.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":37,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0038","version":5,"contentHash":"sha256:ac5a443ba8a10a051eae39a31b452a707815e144d1aac3d303037f06f9eae8fe","question":"Combine the two sentences to make one sentence: John is afraid of roller coasters. He is afraid of heights.","choices":["He is afraid of heights.","Combine the two sentences to make one sentence: John is afraid of roller coasters.","John is afraid of roller coasters and heights.","John is afraid of roller coasters but heights."],"correct":2,"explanation":{"correct":"Answer: John is afraid of roller coasters and heights. By using the conjunction 'and,' we can connect the two noun phrases to avoid repeating 'He is afraid of,' making the sentence more concise.","incorrect":[{"choice":"He is afraid of heights.","category":"incomplete combination","reason":"This choice is just one of the original sentences. Combining sentences means merging the two ideas into a single, flowing statement."},{"choice":"Combine the two sentences to make one sentence: John is afraid of roller coasters.","category":"instructional text error","reason":"This choice accidentally includes the directions from the prompt rather than the actual combined sentence. Always double-check that you are selecting the final sentence, not the question instructions."},"",{"choice":"John is afraid of roller coasters but heights.","category":"improper conjunction","reason":"The word 'but' is used to show contrast or a difference. Since the speaker is afraid of both things, 'and' is the better conjunction to link them together."}]},"studyAid":{"definition":"You can combine two sentences that share the same subject and verb by joining the different parts with a conjunction like 'and' or 'or'.","example":"I like cake and I like pie. -> I like cake and pie. / She plays soccer and she plays tennis. -> She plays soccer and tennis.","strategyClue":"Look for the words that are repeated in both sentences. Keep those words once, and use a conjunction to connect the unique information from each sentence.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":38,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0039","version":5,"contentHash":"sha256:98bdb0f14898bdac2990722d485b9f24c4ece0cace9e9975c00401efb1c5ac09","question":"Combine the two sentences to make one sentence: May I borrow a sweater? May I borrow the blue one?","choices":["May I borrow the blue sweater?","May I borrow a sweater?","May I borrow the blue one?","May I borrow a sweater may I borrow the blue one?"],"correct":0,"explanation":{"correct":"Answer: May I borrow the blue sweater? Combining sentences helps you avoid repeating words by replacing the redundant noun with a descriptive phrase.","incorrect":["",{"choice":"May I borrow a sweater?","category":"missing key details","reason":"This choice loses the specific information about which sweater you want. A good combined sentence keeps the important details from both original sentences."},{"choice":"May I borrow the blue one?","category":"missing key details","reason":"While this is grammatically correct, it leaves out the original noun 'sweater'. Combining sentences should focus on making the final sentence clear and complete."},{"choice":"May I borrow a sweater may I borrow the blue one?","category":"run-on sentence","reason":"This is a run-on sentence because it simply smushes the two thoughts together without a conjunction or punctuation to bridge them."}]},"studyAid":{"definition":"You can combine two sentences into one by identifying the shared noun and using adjectives or phrases to describe it clearly in a single thought.","example":"Original: I have a dog. He is brown. Combined: I have a brown dog. Original: She wants a book. It is new. Combined: She wants a new book.","strategyClue":"Identify the word that appears in both sentences, then try to move the descriptive word (the adjective) to the front of that noun to create one clear sentence.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":39,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0040","version":5,"contentHash":"sha256:0d8131298c5e89464c2f98bb4df287c47296622be87b5bd4fae9558e6d1515e2","question":"Combine the two sentences to make one sentence: Go to bed early. Don't watch too much TV.","choices":["Go to bed early, and don't watch too much TV.","Combine the two sentences to make one sentence: Go to bed early.","Don't watch too much TV.","Go to bed early, but don't watch too much TV."],"correct":0,"explanation":{"correct":"Answer: Go to bed early, and don't watch too much TV. The word 'and' is a coordinating conjunction used to join two related instructions together smoothly in one sentence.","incorrect":["",{"choice":"Combine the two sentences to make one sentence: Go to bed early.","category":"incomplete sentence combination","reason":"This choice ignores the second instruction entirely instead of joining it with the first one."},{"choice":"Don't watch too much TV.","category":"incomplete sentence combination","reason":"This choice ignores the first instruction. To combine them, you must include information from both original sentences."},{"choice":"Go to bed early, but don't watch too much TV.","category":"incorrect conjunction choice","reason":"The word 'but' is used to show a contrast or surprise between two ideas. Since these are two pieces of advice that work together, 'and' is the correct connector."}]},"studyAid":{"definition":"A conjunction is a word used to connect words, phrases, or clauses. The acronym FANBOYS (For, And, Nor, But, Or, Yet, So) helps you remember common joining words.","example":"Eat your vegetables and drink your milk. I wanted to play but it was raining.","strategyClue":"Decide if the two sentences are telling you to do things that go together (use 'and') or if the second part contradicts the first (use 'but').","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":40,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0041","version":5,"contentHash":"sha256:12b1c3b998a5100ff147f0d39d98e777be713a39510559b9d660919c3c982134","question":"Combine the two sentences to make one sentence: Our Christmas tree has white lights. The lights blink.","choices":["Our Christmas tree has white lights that blink.","Our Christmas tree has white lights.","The lights blink.","Our Christmas tree has white lights the lights blink."],"correct":0,"explanation":{"correct":"Answer: Our Christmas tree has white lights that blink. Using the relative pronoun 'that' allows you to join two related ideas about the same object into a single, flowing sentence.","incorrect":["",{"choice":"Our Christmas tree has white lights.","category":"missing information","reason":"This choice only tells us about the color of the lights. It leaves out the important detail that the lights are blinking."},{"choice":"The lights blink.","category":"missing context","reason":"This sentence tells us what the lights are doing, but it fails to mention that the lights belong to the Christmas tree."},{"choice":"Our Christmas tree has white lights the lights blink.","category":"run-on sentence","reason":"When you join two complete thoughts together without a connecting word or proper punctuation, you create a run-on sentence."}]},"studyAid":{"definition":"A complex sentence connects two related ideas using a connecting word like 'that', 'which', or 'who' to make the writing smoother.","example":"The dog is hungry. The dog barked. -> The dog that is hungry barked. / The cat has soft fur. It is gray. -> The cat has soft fur that is gray.","strategyClue":"Identify the noun being described in both sentences and try replacing the repetition of that noun with a word like 'that' to bridge the two ideas together.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":41,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0042","version":5,"contentHash":"sha256:d7647ed8d8f76e291bc7f6d9c1d8a752d86a6424889a45e343153965875d141d","question":"Combine the two sentences to make one sentence: Mrs. Williams' baby is a girl. She is due in April.","choices":["Mrs.","Williams' baby is a girl.","Mrs williams' baby is a girl.","Mrs?"],"correct":0,"explanation":{"correct":"Answer: Mrs. The correct way to combine these sentences is to use a pronoun to refer to the baby, resulting in: 'Mrs. Williams' baby is a girl, and she is due in April.'","incorrect":["",{"choice":"Williams' baby is a girl.","category":"incomplete sentence combination","reason":"This choice ignores the second sentence entirely. Combining sentences means including the key information from both parts."},{"choice":"Mrs williams' baby is a girl.","category":"missing capitalization","reason":"Titles like 'Mrs.' must always be capitalized because they are proper nouns used before a name."},{"choice":"Mrs?","category":"incorrect punctuation mark","reason":"A question mark is used at the end of a sentence that asks something. Since this is a statement of fact, you need a period instead."}]},"studyAid":{"definition":"To combine two related sentences, use a comma and a coordinating conjunction (like 'and', 'but', or 'or') to join them together.","example":"Original: I like pizza. It is tasty. Combined: I like pizza, and it is tasty.","strategyClue":"Look for the subject in the second sentence that refers back to the first sentence, and use a connecting word to link the two thoughts together.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":42,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0043","version":5,"contentHash":"sha256:2d177a0bb5c014bc68e91e65a3e2a14f979fdb100c669989f609cd310db38d5b","question":"Combine the two sentences to make one sentence: I have a friend. Her name is Peaches.","choices":["I have a friend named Peaches.","I have a friend.","Her name is Peaches.","I have a friend her name is Peaches."],"correct":0,"explanation":{"correct":"Answer: I have a friend named Peaches. Using a participle phrase like 'named Peaches' combines the two sentences smoothly into one, avoiding repetition and keeping the focus on the friend.","incorrect":["",{"choice":"I have a friend.","category":"Incomplete information","reason":"This choice ignores the second sentence entirely. To combine them, you must include the information about the name 'Peaches'."},{"choice":"Her name is Peaches.","category":"Incomplete information","reason":"This choice misses the first sentence. A combined sentence needs to link both the fact that you have a friend and her name."},{"choice":"I have a friend her name is Peaches.","category":"Run-on sentence","reason":"This creates a run-on because two independent sentences are stuck together without any punctuation or connecting word to join them properly."}]},"studyAid":{"definition":"To combine sentences, look for repeating ideas and use joining words or phrases to connect them into a single, smooth thought.","example":"Original: I have a cat. Its name is Mittens. Combined: I have a cat named Mittens. Original: He is fast. He is also smart. Combined: He is both fast and smart.","strategyClue":"Look for words that are repeated in both sentences. Try to remove the extra words and use one descriptive phrase to connect the main subject to the extra detail.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":43,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0044","version":5,"contentHash":"sha256:1786c3df66ae2cd0f2268002dcea1576c20b15ef40e88cf1313fb4c9ed6d23d1","question":"Combine the two sentences to make one sentence: I got a kitten at the animal shelter. I named her Tacie.","choices":["I got a kitten at the animal shelter and named her Tacie.","I named her Tacie.","I got a kitten at the animal shelter but named her Tacie.","Combine the two sentences to make one sentence: I got a kitten at the animal shelter."],"correct":0,"explanation":{"correct":"Answer: I got a kitten at the animal shelter and named her Tacie. This is the correct choice because it uses the coordinating conjunction 'and' to connect two related actions performed by the same subject into one smooth sentence.","incorrect":["",{"choice":"I named her Tacie.","category":"Incomplete sentence combination","reason":"This choice only repeats one part of the original information. A combined sentence needs to include both original ideas."},{"choice":"I got a kitten at the animal shelter but named her Tacie.","category":"Incorrect conjunction choice","reason":"The word 'but' is used to show contrast or a surprise. Since naming a kitten is a logical next step after getting one, 'and' is a better choice than 'but'."},{"choice":"Combine the two sentences to make one sentence: I got a kitten at the animal shelter.","category":"Instruction repetition error","reason":"This choice simply repeats the prompt's instruction rather than performing the task of combining the two sentences."}]},"studyAid":{"definition":"You can combine two sentences that have the same subject by using a coordinating conjunction (like and, but, or so) to connect the actions.","example":"He walked to the store. He bought a ball. -> He walked to the store and bought a ball.","strategyClue":"Look for the subject in both sentences. If the subject is the same, keep it once at the beginning and use a conjunction to link the two actions together.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":44,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0045","version":5,"contentHash":"sha256:03396e05862f7420f30e0175ea11722da4cd299d65532be07a0cd663b04e2d4c","question":"Combine the two sentences to make one sentence: Nate is late for a meeting. It started at 4:45.","choices":["Nate is late for a meeting that started at 4:45.","Nate is late for a meeting.","It started at 4:45.","Nate is late for a meeting it started at 4:45."],"correct":0,"explanation":{"correct":"Answer: Nate is late for a meeting that started at 4:45. Using the relative pronoun 'that' connects the two ideas into one smooth sentence by describing which meeting Nate is late for.","incorrect":["",{"choice":"Nate is late for a meeting.","category":"incomplete information","reason":"This choice ignores the second sentence entirely. To combine the sentences, you must include the information about when the meeting started."},{"choice":"It started at 4:45.","category":"incomplete information","reason":"This choice keeps only the second sentence and leaves out the main subject, Nate. A combined sentence should include parts from both original thoughts."},{"choice":"Nate is late for a meeting it started at 4:45.","category":"run-on sentence","reason":"This is a run-on sentence because it tries to stick two complete thoughts together without a connecting word like 'that' or a punctuation mark."}]},"studyAid":{"definition":"You can combine two sentences into one by using words like 'that', 'which', or 'who' to show how the ideas are related.","example":"Correct: I have a dog that loves to run. Incorrect: I have a dog. It loves to run.","strategyClue":"Look for the repeated noun in both sentences. Try replacing the start of the second sentence with a connecting word like 'that' to link the two pieces of information together.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":45,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0046","version":5,"contentHash":"sha256:f553652c4da5da8a0a934baf3206e20b0c2b406826e48423c3ff5113a4b5bee4","question":"Combine the two sentences to make one sentence: Glenda got her ears pierced. She was in third grade.","choices":["Glenda got her ears pierced when she was in third grade.","Glenda got her ears pierced.","She was in third grade.","Glenda got her ears pierced she was in third grade."],"correct":0,"explanation":{"correct":"Answer: Glenda got her ears pierced when she was in third grade. By adding the subordinating conjunction 'when', you link the two ideas together into one smooth, complex sentence that explains exactly when the action happened.","incorrect":["",{"choice":"Glenda got her ears pierced.","category":"missing information","reason":"This sentence leaves out the important detail about when it happened. To combine the sentences, you must include information from both original parts."},{"choice":"She was in third grade.","category":"missing information","reason":"This sentence only tells us the time, but loses the main action of the first sentence. A good combination keeps the meaning of both parts."},{"choice":"Glenda got her ears pierced she was in third grade.","category":"run-on sentence","reason":"This is a run-on sentence because two complete ideas are pushed together without a joining word or punctuation. It needs a word like 'when' or 'while' to connect the ideas properly."}]},"studyAid":{"definition":"A complex sentence combines two ideas into one by using a joining word (like 'when', 'because', or 'if') to show how the ideas relate.","example":"He ate lunch when he got home. She studied because she had a test.","strategyClue":"Identify the main action and the time or reason provided in the two sentences. Look for the choice that uses a connector to bridge those two ideas into one complete, flowing sentence.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":46,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0047","version":5,"contentHash":"sha256:e26603cc1f492c13256d797c079fd0ec763bbdcfd86447dc7cb015d885aa20ba","question":"Combine the two sentences to make one sentence: I need to check out a book. The library is closed.","choices":["I need to check out a book, but the library is closed.","I need to check out a book.","The library is closed.","I need to check out a book the library is closed."],"correct":0,"explanation":{"correct":"Answer: I need to check out a book, but the library is closed. Using the conjunction 'but' connects these two sentences because they represent opposing ideas, creating a clear relationship between the actions.","incorrect":["",{"choice":"I need to check out a book.","category":"incomplete information","reason":"This choice only includes the first half of the original information, leaving out the important detail about the library being closed."},{"choice":"The library is closed.","category":"missing key detail","reason":"This choice ignores the reason you mentioned wanting to check out a book. A combined sentence should include all the original information."},{"choice":"I need to check out a book the library is closed.","category":"run-on sentence","reason":"This is a run-on sentence. Without a joining word like 'but' and a comma, these two complete thoughts are smashed together, making it hard to read."}]},"studyAid":{"definition":"A conjunction like 'but', 'and', or 'or' is used to join two short sentences together into one smooth, longer sentence.","example":"I like cats, but I am allergic. She wanted to play, and he wanted to read.","strategyClue":"Ask yourself if the two ideas go together smoothly or if they seem to conflict. Choose a connecting word that explains the relationship between the two parts of the sentence.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":47,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0048","version":5,"contentHash":"sha256:ce37131e62170e30f42464065d5d8cb1d5db83eb7c6face36291b47be2a9897a","question":"Combine the two sentences to make one sentence: We rafted down the Ocoee River. The rafting trip lasted six hours.","choices":["The rafting trip lasted six hours.","We rafted down the Ocoee River, and the rafting trip lasted six hours.","We rafted down the Ocoee River, but the rafting trip lasted six hours.","Combine the two sentences to make one sentence: We rafted down the Ocoee River."],"correct":1,"explanation":{"correct":"Answer: We rafted down the Ocoee River, and the rafting trip lasted six hours. Using the coordinating conjunction 'and' connects two independent, related ideas into one smooth compound sentence.","incorrect":[{"choice":"The rafting trip lasted six hours.","category":"missing information","reason":"This choice ignores the first sentence entirely. A good combination should include the main details from both original sentences."},"",{"choice":"We rafted down the Ocoee River, but the rafting trip lasted six hours.","category":"incorrect conjunction","reason":"The word 'but' is used to show contrast or conflict. Since these two ideas support each other, 'and' is the better connector."},{"choice":"Combine the two sentences to make one sentence: We rafted down the Ocoee River.","category":"instruction error","reason":"This choice repeats the prompt instructions instead of providing the combined sentence. Always double-check that you have included both ideas."}]},"studyAid":{"definition":"A compound sentence joins two complete thoughts together using a comma and a coordinating conjunction (like 'and', 'but', or 'or').","example":"I like cats, and my sister likes dogs. It was raining, so we stayed inside.","strategyClue":"Identify the two separate actions or facts in the prompt and determine if they agree with each other or conflict, then select the conjunction that best fits that relationship.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":48,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0049","version":5,"contentHash":"sha256:44bcfe06d69d78b3b3c291105910ee51c43b1b18f61922ac1c9b5cc288479b24","question":"Combine the two sentences to make one sentence: The quarterback threw the ball. The receiver dropped it.","choices":["The quarterback threw the ball, but the receiver dropped it.","The quarterback threw the ball.","The receiver dropped it.","The quarterback threw the ball the receiver dropped it."],"correct":0,"explanation":{"correct":"Answer: The quarterback threw the ball, but the receiver dropped it. To combine two complete sentences, you must use a comma and a coordinating conjunction like 'but' to show the contrast between the throw and the drop.","incorrect":["",{"choice":"The quarterback threw the ball.","category":"incomplete information","reason":"This choice only includes the first sentence. To combine the ideas, you must include information from both original sentences."},{"choice":"The receiver dropped it.","category":"incomplete information","reason":"This choice only includes the second sentence. It misses the important context provided in the first sentence about the quarterback throwing the ball."},{"choice":"The quarterback threw the ball the receiver dropped it.","category":"run-on sentence","reason":"This creates a run-on sentence. Two independent thoughts need a conjunction and a comma to be linked together properly in one sentence."}]},"studyAid":{"definition":"A compound sentence is formed by joining two independent sentences with a comma and a coordinating conjunction (for, and, nor, but, or, yet, so).","example":"I like cake, but he likes pie. / It was raining, so we stayed inside.","strategyClue":"Identify the two separate actions happening, then choose the joining word that best describes how those actions relate to each other—either as an addition or a contrast.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":49,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0050","version":5,"contentHash":"sha256:89d4f8adeb0ddac6565b29f46762d7682849df3529cb97196b32a0e70d7fc837","question":"Combine the two sentences to make one sentence: Juan can recite the alphabet backwards. I can also do it.","choices":["I can also do it.","Juan can recite the alphabet backwards, and I can also do it.","Juan can recite the alphabet backwards, but I can also do it.","Combine the two sentences to make one sentence: Juan can recite the alphabet backwards."],"correct":1,"explanation":{"correct":"Answer: Juan can recite the alphabet backwards, and I can also do it. Using the coordinating conjunction 'and' correctly connects two related independent clauses to form a single compound sentence.","incorrect":[{"choice":"I can also do it.","category":"fragmented sentence structure","reason":"This choice ignores the first part of the prompt. A combination must include information from both original sentences."},"",{"choice":"Juan can recite the alphabet backwards, but I can also do it.","category":"conjunction usage error","reason":"The conjunction 'but' is used for contrasting ideas. Since both people can do the same task, 'and' is the logical choice to show addition."},{"choice":"Combine the two sentences to make one sentence: Juan can recite the alphabet backwards.","category":"instruction misinterpretation","reason":"This choice simply repeats the prompt instructions instead of performing the task of combining the two ideas into a new sentence."}]},"studyAid":{"definition":"A compound sentence is formed by joining two complete, related ideas using a comma and a coordinating conjunction (for, and, nor, but, or, yet, so).","example":"He ran fast, and he won the race. It was raining, but we played outside anyway.","strategyClue":"Look at the relationship between the two ideas: are they similar and adding to each other, or are they showing a difference? Choose the conjunction that matches that connection.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":50,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0051","version":5,"contentHash":"sha256:b51a48c0f20d595ebff665e9e3f2e08cf451cf09e6adef4213e25a227f8d52aa","question":"Combine the two sentences to make one sentence: Poinsettias are pretty plants. They are red.","choices":["Poinsettias are pretty red plants.","Poinsettias are pretty plants.","They are red.","Poinsettias are pretty plants they are red."],"correct":0,"explanation":{"correct":"Answer: Poinsettias are pretty red plants. By moving the adjective 'red' into the first sentence, you create a more concise sentence that describes the plant using all provided information without repeating the subject.","incorrect":["",{"choice":"Poinsettias are pretty plants.","category":"incomplete information","reason":"This choice misses the important detail that the plants are red. A good combination should include the key information from both sentences."},{"choice":"They are red.","category":"incomplete information","reason":"This choice ignores the subject of the original sentence ('Poinsettias') and the description that they are pretty plants."},{"choice":"Poinsettias are pretty plants they are red.","category":"run-on sentence","reason":"This is a run-on sentence. Two complete thoughts are joined together without the correct punctuation or a connecting word like 'and'."}]},"studyAid":{"definition":"To combine sentences effectively, you can take a descriptive word from one sentence and move it into the other to avoid repeating the subject.","example":"The dog is big. The dog is brown. -> The big brown dog is here. The car is fast. The car is blue. -> The fast blue car is mine.","strategyClue":"Look for adjectives in the second sentence that describe the subject in the first sentence. Try to place that adjective in front of the noun instead of keeping two separate sentences.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":51,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0052","version":5,"contentHash":"sha256:eaacc4f523943eb4b03154aa9a9dcd9f35373e380b1d4f1c2b374506e4d718fc","question":"Combine the two sentences to make one sentence: The battery on the radio went dead. We need a new one.","choices":["The battery on the radio went dead, so we need a new one.","The battery on the radio went dead.","We need a new one.","The battery on the radio went dead we need a new one."],"correct":0,"explanation":{"correct":"Answer: The battery on the radio went dead, so we need a new one. Using the coordinating conjunction 'so' connects the cause to the effect, creating a single compound sentence.","incorrect":["",{"choice":"The battery on the radio went dead.","category":"incomplete sentence combination","reason":"This choice only keeps the first half of the original thought. Combining sentences means you must include both ideas in one sentence."},{"choice":"We need a new one.","category":"incomplete sentence combination","reason":"This choice only keeps the second half of the original thought. Both ideas are necessary to fully explain why a new battery is needed."},{"choice":"The battery on the radio went dead we need a new one.","category":"run-on sentence error","reason":"This creates a run-on sentence. When joining two complete sentences, you must use a comma and a conjunction to connect them properly."}]},"studyAid":{"definition":"A compound sentence joins two complete thoughts together using a comma and a coordinating conjunction like 'and', 'but', or 'so'.","example":"I was hungry, so I ate a snack. It was raining, but we played outside anyway.","strategyClue":"Identify the relationship between the two sentences. If the second part happens because of the first, look for a connecting word that shows cause and effect, and remember to use a comma before it.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":52,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0053","version":5,"contentHash":"sha256:ee8563234bb222530c28b847459033bc6c395d8fa41be2174b27f93337f6c626","question":"Combine the two sentences to make one sentence: Her family is visiting from Athens, Georgia. They will be here for a week.","choices":["Her family is visiting from Athens, Georgia, but they will be here for a week.","They will be here for a week.","Combine the two sentences to make one sentence: Her family is visiting from Athens, Georgia.","Her family is visiting from Athens, Georgia, and they will be here for a week."],"correct":3,"explanation":{"correct":"Answer: Her family is visiting from Athens, Georgia, and they will be here for a week. The conjunction 'and' correctly connects two related ideas into one compound sentence.","incorrect":[{"choice":"Her family is visiting from Athens, Georgia, but they will be here for a week.","category":"incorrect conjunction","reason":"The word 'but' is used to show contrast or conflict. Since these two sentences are just adding information, 'and' is the better choice."},{"choice":"They will be here for a week.","category":"incomplete combination","reason":"This choice ignores half of the information. To combine sentences, you must include the ideas from both original sentences in your final answer."},{"choice":"Combine the two sentences to make one sentence: Her family is visiting from Athens, Georgia.","category":"instruction error","reason":"This choice just repeats the question prompt instead of performing the task of combining the two sentences."},""]},"studyAid":{"definition":"A compound sentence joins two complete thoughts together using a comma and a coordinating conjunction like 'and', 'but', or 'or'.","example":"I like cake, and I like pie. It was raining, but we played outside anyway.","strategyClue":"Look at the relationship between the two ideas: do they support each other or clash? If they simply add onto each other, use a connecting word that signifies addition rather than opposition.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":53,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0054","version":5,"contentHash":"sha256:ed96b3f44d9a18e31479450e26a51f5818833c604f33ee40d4184185e3ed20d0","question":"Combine the two sentences to make one sentence: I've heard that song on the radio. I don't remember who sings it.","choices":["I've heard that song on the radio, but I don't remember who sings it.","I've heard that song on the radio.","I don't remember who sings it.","I've heard that song on the radio i don't remember who sings it."],"correct":0,"explanation":{"correct":"Answer: I've heard that song on the radio, but I don't remember who sings it. Using a comma and the coordinating conjunction 'but' correctly joins two independent thoughts while showing that they contrast each other.","incorrect":["",{"choice":"I've heard that song on the radio.","category":"incomplete sentence combination","reason":"This only includes the first half of the thought. Combining sentences requires keeping both pieces of information and linking them together."},{"choice":"I don't remember who sings it.","category":"missing information","reason":"This choice leaves out the first part of the sentence entirely. A good combination should include the information from both original sentences."},{"choice":"I've heard that song on the radio i don't remember who sings it.","category":"run-on sentence","reason":"This is a run-on because it pushes two independent sentences together without any punctuation or a connecting word to separate them."}]},"studyAid":{"definition":"A compound sentence joins two complete thoughts together using a comma and a conjunction like 'and', 'but', or 'or'.","example":"I like cake, but my brother likes pie. / It was raining, so I brought my umbrella.","strategyClue":"Look for a connector that fits the relationship between the two ideas, and check for a comma before that word to avoid a run-on.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":54,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0055","version":5,"contentHash":"sha256:059b586d6358964257dffd6025e5a64ccdcede0d07b2bb9f25efae5807d220f6","question":"Combine the two sentences to make one sentence: Reagan's dad is my dentist. He is very nice.","choices":["Reagan's dad, who is my dentist, is very nice.","Reagan's dad is my dentist.","He is very nice.","Reagan's dad is my dentist he is very nice."],"correct":0,"explanation":{"correct":"Answer: Reagan's dad, who is my dentist, is very nice. Using the relative pronoun 'who' connects the two ideas into one smooth sentence by describing the subject.","incorrect":["",{"choice":"Reagan's dad is my dentist.","category":"incomplete task","reason":"This is only one of the two original sentences. A combined sentence must include the information from both parts."},{"choice":"He is very nice.","category":"incomplete task","reason":"This choice ignores the first sentence entirely. Combining sentences requires merging all the important details into one new statement."},{"choice":"Reagan's dad is my dentist he is very nice.","category":"run-on sentence","reason":"This creates a run-on sentence. You need a connector like 'who' or a punctuation mark to link two independent thoughts together properly."}]},"studyAid":{"definition":"A complex sentence uses a connecting word to join two ideas, turning one of them into a description of the other.","example":"The dog is loud. The dog is mine. -> The dog, which is loud, is mine.","strategyClue":"Look for the common noun or person mentioned in both sentences, then think about which word can act as a bridge to describe that person.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":55,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0056","version":5,"contentHash":"sha256:51be0ea7ed125fd68d9c1f1ee5374e551a51ef1890cb886dca616c86d0847805","question":"Combine the two sentences to make one sentence: We walk the dog after dinner. We walk a mile and a half.","choices":["We walk the dog a mile and a half after dinner.","We walk a mile and a half.","Combine the two sentences to make one sentence: We walk the dog after dinner.","We walk the dog a mile but a half after dinner."],"correct":0,"explanation":{"correct":"Answer: We walk the dog a mile and a half after dinner. This sentence correctly combines the actions and details from both original sentences into a single, cohesive thought.","incorrect":["",{"choice":"We walk a mile and a half.","category":"missing information","reason":"This choice leaves out the important detail about walking the dog, making it an incomplete representation of the original two sentences."},{"choice":"Combine the two sentences to make one sentence: We walk the dog after dinner.","category":"instruction inclusion","reason":"This choice mistakenly includes the prompt's instructions as part of the sentence itself, which makes the sentence confusing and incorrect."},{"choice":"We walk the dog a mile but a half after dinner.","category":"incorrect conjunction usage","reason":"The word 'but' is used here, but it creates a contradiction that doesn't exist in the original sentences. The phrases 'a mile' and 'a half' should be grouped together."}]},"studyAid":{"definition":"A sentence combination takes two separate sentences and joins them using conjunctions or rearranged details to create one smooth, complete thought.","example":"Original: She has a dog. The dog is brown. Combined: She has a brown dog.","strategyClue":"Identify the common subject and action in both sentences, then look for a way to weave the extra details into one sentence without changing the original meaning.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":56,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0057","version":5,"contentHash":"sha256:59f5ceb065dff39e0a5a209c7d18c15bb3b8cce028b82240a1e4d4f2f8c680e6","question":"Combine the two sentences to make one sentence: Hayden is a gymnast. She is very flexible.","choices":["Hayden is a gymnast, so she is very flexible.","Hayden is a gymnast.","She is very flexible.","Hayden is a gymnast she is very flexible."],"correct":0,"explanation":{"correct":"Answer: Hayden is a gymnast, so she is very flexible. Using a comma and a coordinating conjunction like 'so' effectively links two related independent clauses into one fluid sentence.","incorrect":["",{"choice":"Hayden is a gymnast.","category":"Incomplete sentence combination","reason":"This choice only repeats the first sentence. To combine both, you must include the information about her being flexible."},{"choice":"She is very flexible.","category":"Incomplete sentence combination","reason":"This choice only repeats the second sentence. It misses the subject and the important context about her being a gymnast."},{"choice":"Hayden is a gymnast she is very flexible.","category":"Run-on sentence","reason":"This is a run-on sentence. When joining two complete thoughts, you must use a comma and a conjunction (like 'so') to separate them correctly."}]},"studyAid":{"definition":"A compound sentence joins two simple sentences together using a comma and a coordinating conjunction like 'and', 'but', or 'so'.","example":"Simple: He ran fast. / Compound: He ran fast, but he missed the bus.","strategyClue":"Look for the spot where the two sentences meet. Ask yourself if you have added both a comma and a linking word to glue the two separate ideas together.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":57,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0058","version":5,"contentHash":"sha256:3221a3607b2acd6e7aac52de958280038ae136b22086bcf8e4ad4b4fd52ecf54","question":"Combine the two sentences to make one sentence: I asked for a guitar for Christmas. I didn't get the guitar.","choices":["I asked for a guitar for Christmas, but I didn't get it.","I asked for a guitar for Christmas.","I didn't get the guitar.","I asked for a guitar for Christmas i didn't get the guitar."],"correct":0,"explanation":{"correct":"Answer: I asked for a guitar for Christmas, but I didn't get it. Using the conjunction 'but' correctly joins two opposite ideas, and replacing the second 'guitar' with the pronoun 'it' avoids unnecessary repetition.","incorrect":["",{"choice":"I asked for a guitar for Christmas.","category":"incomplete information","reason":"This choice only includes one of the two original sentences, leaving out the important information about not receiving the gift."},{"choice":"I didn't get the guitar.","category":"incomplete information","reason":"This choice only includes the second part of the story, missing the initial request you made for the guitar."},{"choice":"I asked for a guitar for Christmas i didn't get the guitar.","category":"run-on sentence","reason":"This is a run-on sentence because it joins two complete thoughts without a conjunction (like 'but') or proper punctuation to separate them."}]},"studyAid":{"definition":"A compound sentence joins two related ideas using a comma and a coordinating conjunction like 'and', 'but', or 'or'.","example":"I was hungry, but there was no food. / I wanted to play, and she wanted to read.","strategyClue":"Look at the relationship between the two ideas. If one idea happens in spite of the other, use the conjunction that signals a contrast, and make sure to use a comma before it.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":58,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0059","version":5,"contentHash":"sha256:62ce740977c166be14ebe232b81cf8ed9a85065a73d124971c1f16247570b355","question":"Combine the two sentences to make one sentence: The ball came straight to him. He caught it.","choices":["The ball came straight to him, but he caught it.","He caught it.","The ball came straight to him, and he caught it.","Combine the two sentences to make one sentence: The ball came straight to him."],"correct":2,"explanation":{"correct":"Answer: The ball came straight to him, and he caught it. This uses a comma and the coordinating conjunction 'and' to join two related, equal ideas into one smooth sentence.","incorrect":[{"choice":"The ball came straight to him, but he caught it.","category":"incorrect coordinating conjunction","reason":"Using 'but' implies a contradiction or a surprise. Since catching a ball thrown to you is expected, 'and' is the better choice to connect these related actions."},{"choice":"He caught it.","category":"incomplete sentence combination","reason":"This choice ignores the first part of the prompt. When combining sentences, you must include the information from both original sentences in the new one."},"",{"choice":"Combine the two sentences to make one sentence: The ball came straight to him.","category":"misunderstanding task instructions","reason":"This choice repeats the prompt instructions rather than answering the question. You need to join both actions into one combined sentence."}]},"studyAid":{"definition":"A compound sentence joins two simple sentences together using a comma and a coordinating conjunction like 'and', 'but', or 'or'.","example":"He liked the movie, and he told his friends. I wanted pizza, but we had tacos.","strategyClue":"Look at both sentences to see if they share a connection: do they happen in order, or do they contrast? Choose the conjunction that best explains how the two ideas relate to each other.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":59,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0060","version":5,"contentHash":"sha256:1f32a0ac87f513e8ead8a3dd3f7fc2fdbf51fbaf73050e7b8d89282adc625af2","question":"Combine the two sentences to make one sentence: Our team wears blue and white. They are losing now.","choices":["They are losing now.","Combine the two sentences to make one sentence: Our team wears blue and white.","Our team wears blue but white, but they are losing now.","Our team wears blue and white, and they are losing now."],"correct":3,"explanation":{"correct":"Answer: Our team wears blue and white, and they are losing now. Using a comma and the coordinating conjunction 'and' correctly joins two independent thoughts into one smooth sentence.","incorrect":[{"choice":"They are losing now.","category":"incomplete combination","reason":"This choice only uses one of the two original sentences. To combine them, you must include the information from both parts: the team's colors and the fact that they are losing."},{"choice":"Combine the two sentences to make one sentence: Our team wears blue and white.","category":"instruction error","reason":"This choice includes the prompt's instruction text rather than the actual sentences. Make sure to only use the information given in the original sentences."},{"choice":"Our team wears blue but white, but they are losing now.","category":"improper conjunction","reason":"Using 'but' in the first part creates a contradiction where there isn't one. Stick to 'and' for connecting two related facts about the team."},""]},"studyAid":{"definition":"A compound sentence joins two complete ideas together using a comma and a conjunction like 'and', 'but', or 'or'.","example":"I like cats, and I like dogs. The sky is dark, but the stars are bright.","strategyClue":"Look for a conjunction that links the two thoughts logically without adding extra words or repeating instructions. Identify the two main ideas and check which conjunction fits best between them.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":60,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0061","version":5,"contentHash":"sha256:19e19a45f022795d3386ea82588ac5062ca0a2a2b268e29335d9e9f51a1f0223","question":"Combine the two sentences to make one sentence: Rebecca plays tennis on Thursdays. She is very good.","choices":["Rebecca, who plays tennis on Thursdays, is very good.","Rebecca plays tennis on Thursdays.","She is very good.","Rebecca plays tennis on Thursdays she is very good."],"correct":0,"explanation":{"correct":"Answer: Rebecca, who plays tennis on Thursdays, is very good. Using the relative pronoun 'who' allows you to connect the two related ideas about Rebecca into a single, fluid sentence.","incorrect":["",{"choice":"Rebecca plays tennis on Thursdays.","category":"incomplete task","reason":"This is only the first part of the original information; it does not combine both sentences or include the information about how good she is."},{"choice":"She is very good.","category":"missing information","reason":"This choice ignores the first sentence entirely. A combined sentence must include the main points from both original sentences."},{"choice":"Rebecca plays tennis on Thursdays she is very good.","category":"run-on sentence","reason":"This creates a run-on sentence by placing two independent clauses side-by-side without proper punctuation or a connecting word."}]},"studyAid":{"definition":"A complex sentence combines two ideas into one by using connecting words like 'who', 'which', or 'that' to describe a person or object.","example":"Simple: The dog is hungry. The dog barks. Combined: The dog, who is hungry, barks.","strategyClue":"Look for a word that appears in both sentences, like a name or a pronoun. Use that word as your anchor to join the two thoughts together with a describing phrase.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":61,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0062","version":5,"contentHash":"sha256:04e4464dd1aa2b1bd77be139d692ca5ae6bf1b479ec1a6d1a6de1fc0a34c22ec","question":"Combine the two sentences to make one sentence: We got a new computer. It came with a CD-ROM drive.","choices":["We got a new computer that came with a CD-ROM drive.","We got a new computer.","It came with a CD-ROM drive.","We got a new computer it came with a CD-ROM drive."],"correct":0,"explanation":{"correct":"Answer: We got a new computer that came with a CD-ROM drive. By adding the relative pronoun 'that', you connect the two ideas smoothly into one sentence, describing the computer using the second part of the sentence.","incorrect":["",{"choice":"We got a new computer.","category":"Incomplete information","reason":"This choice ignores the second part of the prompt entirely. To combine sentences, you must include the information from both original sentences."},{"choice":"It came with a CD-ROM drive.","category":"Incomplete information","reason":"This choice leaves out the first sentence about getting a computer. Combining sentences means merging the ideas, not just choosing one."},{"choice":"We got a new computer it came with a CD-ROM drive.","category":"Run-on sentence","reason":"This is a run-on sentence. When joining two complete sentences, you must use a connector word like 'that', 'and', or 'which' to link them properly."}]},"studyAid":{"definition":"You can join two sentences together by using connecting words or relative pronouns like 'that', 'which', or 'who' to create a single, clear sentence.","example":"Original: I saw a dog. It was brown. Combined: I saw a dog that was brown.","strategyClue":"Look for a word that can act as a bridge between the noun in the first sentence and the action in the second sentence to turn two thoughts into one.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":62,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0063","version":5,"contentHash":"sha256:71ae8f405f17d1d2d1336ce2e2671b2fe5a77e72862031166179fb31d8dcaf68","question":"Combine the two sentences to make one sentence: The plant has turned brown. It needs water.","choices":["The plant has turned brown because it needs water.","The plant has turned brown so it needs water.","It needs water.","Combine the two sentences to make one sentence: The plant has turned brown."],"correct":0,"explanation":{"correct":"Answer: The plant has turned brown because it needs water. The word 'because' is a subordinating conjunction used to show a cause-and-effect relationship between the two ideas.","incorrect":["",{"choice":"The plant has turned brown so it needs water.","category":"improper conjunction","reason":"While 'so' is a conjunction, it usually indicates a result. In this case, 'because' is a better fit to explain the reason why the plant turned brown."},{"choice":"It needs water.","category":"incomplete combination","reason":"This choice ignores the first part of the prompt. To combine the sentences, both ideas need to be included in the final sentence."},{"choice":"Combine the two sentences to make one sentence: The plant has turned brown.","category":"instructions as answer","reason":"This choice repeats the prompt instructions rather than actually combining the two sentences into one complete thought."}]},"studyAid":{"definition":"Conjunctions like 'because', 'although', or 'since' are joining words that connect two ideas to explain how they relate to each other.","example":"I wore a coat because it was cold. I was tired, so I went to bed early.","strategyClue":"Look for a word that explains the relationship between the two sentences; ask yourself if one part provides a reason for the other part.","link":"https://www.grammar-monster.com/glossary/sentence.htm","linkText":"Grammar Monster - Sentence Structure"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"medium","6":"medium"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-edit","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":63,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0064","version":5,"contentHash":"sha256:7412cfed89be59b0f2cbd82b78e66226e36362ecef12f4aef2c72a9853c1236d","question":"Select the best way to combine these sentences. I missed the bus. I was tardy to my first hour class.","choices":["I missed the bus, but I was tardy to my first hour c lass.","I missed the bus, for I was tardy to my first hour class.","I missed the bus, and I was tardy to my first hour class.","I missed the bus, or I was tardy to my first hour class."],"correct":2,"explanation":{"correct":"Answer: I missed the bus, and I was tardy to my first hour class. The conjunction 'and' is used to connect two related ideas that happen in sequence or share a logical connection where one leads to the other.","incorrect":[{"choice":"I missed the bus, but I was tardy to my first hour c lass.","category":"incorrect coordinating conjunction","reason":"The conjunction 'but' shows contrast or opposition. Since missing the bus naturally leads to being late, 'but' is the wrong choice here."},{"choice":"I missed the bus, for I was tardy to my first hour class.","category":"incorrect coordinating conjunction","reason":"The conjunction 'for' means 'because' and introduces a reason. This sentence implies the tardiness caused you to miss the bus, which is the opposite of the actual cause-and-effect relationship."},"",{"choice":"I missed the bus, or I was tardy to my first hour class.","category":"incorrect coordinating conjunction","reason":"The conjunction 'or' is used to show a choice between two options. This sentence makes it sound like you only had to pick one of those two things to happen, which does not fit the context."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":64,"sourceFile":"Advanced-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":4,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Coordinating conjunctions (FANBOYS: For, And, Nor, But, Or, Yet, So) link words or groups of words together. Choosing the right one depends on whether you are showing addition, contrast, choices, or cause.","example":"I ate pizza and salad (addition). I wanted pizza but we had salad (contrast). Will you eat pizza or salad (choice)?","strategyClue":"Test the meaning of each conjunction by replacing the blank with words like 'in addition,' 'however,' or 'otherwise' to see which word best explains how the two ideas relate to each other.","link":"","linkText":""}},{"id":"grammar-sentence-combinations-q0065","version":4,"contentHash":"sha256:a524c5f28c658fcc24f994995f7f91ac95b5c526406d53cfadd676d85da41c03","question":"Choose the best coordinating conjunction to complete the sentence below. I brought cookies to share, _____ I didn’t bring enough for everyone.","choices":["but","and","or","so"],"correct":0,"explanation":{"correct":"Answer: but. The word 'but' is used to connect two ideas that contrast or show a difference. Since bringing cookies and not having enough for everyone are opposite or unexpected results, 'but' is the correct conjunction.","incorrect":["",{"choice":"and","category":"conjunction for addition","reason":"'And' is used to join two similar ideas or to list things that go together. It doesn't make sense here because the second part of the sentence contrasts with the first part."},{"choice":"or","category":"conjunction for choice","reason":"'Or' is used to show an option or a choice between two things. It isn't right here because the sentence isn't offering a decision between cookies and not having enough."},{"choice":"so","category":"conjunction for cause","reason":"'So' is used to show a result or a reason. 'I brought cookies, so I didn't bring enough' implies that bringing cookies caused you not to have enough, which doesn't fit the logic of the sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":65,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":19,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Coordinating conjunctions connect words, phrases, or clauses. Use 'but' to show contrast, 'and' to add information, 'so' to show a result, and 'or' to show a choice.","example":"I like cake but hate pie (contrast); I like cake and pie (addition); I like cake, so I bought one (result); Do you want cake or pie? (choice)","strategyClue":"Look at the two ideas in the sentence. Ask yourself: Do they agree and add to each other, or does the second part say something unexpected or opposite to the first part?","link":"","linkText":""}},{"id":"grammar-sentence-combinations-q0066","version":4,"contentHash":"sha256:012aa6206d181cd220dedddbbe8ca9a887eca57c4f83e288cf567db85cc4bb79","question":"Which sentence is a compound sentence?","choices":["I fed the pigs, and they snorted happily.","I fed the pigs and snorted happily.","I fed the pigs, they snorted happily.","I fed pigs. And they snorted happily."],"correct":0,"explanation":{"correct":"Answer: I fed the pigs, and they snorted happily. A compound sentence contains two independent clauses joined by a comma and a coordinating conjunction like 'and'.","incorrect":["",{"choice":"I fed the pigs and snorted happily.","category":"simple sentence structure","reason":"This is a simple sentence with a compound predicate. Because there is only one subject performing both actions, it does not have two independent clauses."},{"choice":"I fed the pigs, they snorted happily.","category":"comma splice error","reason":"This is a comma splice. You cannot join two independent clauses with only a comma; you must include a conjunction like 'and', 'but', or 'so' after the comma."},{"choice":"I fed pigs. And they snorted happily.","category":"sentence fragment","reason":"Starting a sentence with 'And' is usually discouraged in formal writing, and in this case, it creates two separate sentences rather than one compound sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":66,"sourceFile":"Basic-5_Writing strategies_Application_Style.pdf","sourceQuestionNumber":1,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A compound sentence is made of two complete sentences (independent clauses) joined by a comma and a coordinating conjunction (FANBOYS: for, and, nor, but, or, yet, so).","example":"Simple: He ran. / Compound: He ran, and he jumped.","strategyClue":"Look for a comma followed by a connecting word. Check if the words on both sides of the comma can stand alone as complete, separate sentences.","link":"","linkText":""}},{"id":"grammar-sentence-combinations-q0067","version":5,"contentHash":"sha256:8697a0cfc71b441789fa04c8fc7e77707c0a88f4aa2d705ececba0f8fec66e67","question":"Which is the best way to combine these sentences? Cindy packed three pairs of shoes. Cindy packed two pairs of jeans.","choices":["Cindy packed three pairs of shoes and then sh e packed two pairs of jeans.","Cindy packed three pairs of shoes and two pairs of jeans.","Cindy packed three pairs of shoes or two pairs of jeans.","Cindy packed three pairs of shoes, but then she packed two pairs of jeans."],"correct":1,"explanation":{"correct":"Answer: Cindy packed three pairs of shoes and two pairs of jeans. The conjunction 'and' is the most efficient way to link two related ideas where the subject and verb are the same.","incorrect":[{"choice":"Cindy packed three pairs of shoes and then sh e packed two pairs of jeans.","category":"repetitive phrasing","reason":"Repeating the subject 'she' and the verb 'packed' makes the sentence clunky. Combine the objects after the first verb to keep your writing concise."},"",{"choice":"Cindy packed three pairs of shoes or two pairs of jeans.","category":"incorrect conjunction meaning","reason":"Using 'or' suggests a choice between the two items, implying she could only pick one. Since she packed both, 'and' is the correct conjunction to use."},{"choice":"Cindy packed three pairs of shoes, but then she packed two pairs of jeans.","category":"misused contrastive conjunction","reason":"The word 'but' is used to show contrast or surprise. Since packing shoes and jeans are two similar actions of packing luggage, there is no need for 'but'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":67,"sourceFile":"Basic-5_Writing strategies_Application_Style.pdf","sourceQuestionNumber":7,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Use a conjunction like 'and' to join two simple sentences into one compound sentence, especially when you are describing a list of items done by the same person.","example":"I like apples and I like pears. -> I like apples and pears. She went to the park and she went to the store. -> She went to the park and the store.","strategyClue":"Look at the verbs and subjects in both sentences. If they are the same, try to keep the subject and verb only once and connect the different objects with a joining word.","link":"","linkText":""}},{"id":"grammar-sentence-combinations-q0068","version":5,"contentHash":"sha256:17ab38ffda6bb483dd0ccbe317e6b4c93d52042806966745990c03eb0e266b0a","question":"Read the 3 sentences below. The baby opened the cabinet. She took out all the cans. She smiled and giggled. Which is the best way to combine the 3 sentences.","choices":["The baby opened the cabinet and took out all the cans and smiled.","After the baby took all the cans outof the cabinet, she smiled and giggle d.","The bab y took out all the cans and smiled then giggled.","The baby opened a cabinet and took out all of the cans from the cabinet."],"correct":1,"explanation":{"correct":"Answer: After the baby took all the cans out of the cabinet, she smiled and giggled. This option effectively uses a subordinate conjunction ('After') to show the order of events and avoids repetitive phrasing.","incorrect":[{"choice":"The baby opened the cabinet and took out all the cans and smiled.","category":"repetitive conjunction use","reason":"Using 'and' twice in one sentence makes the flow clunky. It is better to use different transition words to show the timing of actions."},"",{"choice":"The bab y took out all the cans and smiled then giggled.","category":"missing sentence details","reason":"This choice leaves out the action of opening the cabinet, which is a key part of the original sequence of events."},{"choice":"The baby opened a cabinet and took out all of the cans from the cabinet.","category":"redundant word usage","reason":"Repeating the word 'cabinet' twice makes the sentence awkward. Using pronouns or rephrasing helps make the sentence tighter and clearer."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sequence":68,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":33,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Sentence combining is the process of joining short, choppy sentences into one smooth sentence using conjunctions or transition words to show how ideas relate.","example":"Choppy: The dog ran. The dog barked. Combined: The dog ran and barked.","strategyClue":"Identify the order of the actions first. Look for the choice that captures all three actions in the correct order without repeating words unnecessarily.","link":"","linkText":""}},{"id":"grammar-sentence-combinations-q0081","version":5,"contentHash":"sha256:56fcc67a6b8b523883333fb9553ddd9d8efcb9b2a34de9f3589c83758f052564","question":"Choose the transition word(s) that introduces an example.","choices":["in conclusion","for instance","never","previously"],"correct":1,"explanation":{"correct":"Answer: for instance. Transition phrases like 'for instance' and 'for example' are used to signal that a specific illustration or piece of evidence follows to support a previous statement.","incorrect":[{"choice":"in conclusion","category":"closing transition error","reason":"'In conclusion' is used to summarize main ideas at the end of a piece of writing, not to introduce a specific example."},"",{"choice":"never","category":"time transition error","reason":"'Never' is an adverb used to talk about time or frequency, not a phrase meant to signal an illustration or example."},{"choice":"previously","category":"sequence transition error","reason":"'Previously' refers to things that happened in the past or earlier in the text, rather than providing an example of the current point."}]},"studyAid":{"definition":"Transition words are bridges that help a reader move between ideas. Certain transitions act as 'signposts' to show when a specific example is coming.","example":"Cats are independent; for instance, they can entertain themselves for hours. My brother has many hobbies, such as painting and swimming.","strategyClue":"Ask yourself: Does the sentence following this word explain or prove the point made just before it? If yes, look for a phrase that introduces an illustration.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":30,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":81,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0088","version":5,"contentHash":"sha256:c168ce3b0fcc3f884d08ee50f0d18dea02086eb78a5b63dbb2cf75f78b6572ad","question":"Choose the transition that shows emphasis.","choices":["too","finally","certainly","or"],"correct":2,"explanation":{"correct":"Answer: certainly. This word acts as an adverb to emphasize the truth or importance of a statement, making it the correct choice for showing emphasis.","incorrect":[{"choice":"too","category":"addition transition","reason":"The word 'too' is used to show addition or agreement (meaning 'also'), not to place special importance or emphasis on a point."},{"choice":"finally","category":"sequencing transition","reason":"'Finally' is used to show the last step in a sequence or process, whereas the sentence requires a word to stress a specific fact."},"",{"choice":"or","category":"alternative conjunction","reason":"'Or' is a coordinating conjunction used to show a choice between two things, which does not provide the intended emphasis for the statement."}]},"studyAid":{"definition":"Emphasis transitions are words used to highlight, stress, or show the importance of a specific idea or fact in your writing.","example":"Certainly, you may go. Indeed, it was a cold day. Truly, that was the best show ever.","strategyClue":"Test the transition by replacing it with a synonym like 'without a doubt' or 'definitely'. If the word fits that meaning, it is likely the correct emphasis transition.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":37,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":88,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0183","version":5,"contentHash":"sha256:d1a4198aef69ac19513f3eb02bb3b9a9c61e40d07fff1161082e0fa144e5733e","question":"Choose the transition that shows cause and effect.","choices":["certainly","as a result","soon","opposite"],"correct":1,"explanation":{"correct":"Answer: as a result. This phrase signals a cause-and-effect relationship, indicating that the second part of the sentence happens because of the event described in the first part.","incorrect":[{"choice":"certainly","category":"adverb of certainty","reason":"This word shows how sure you are about something, not the cause of an event. It doesn't connect two ideas with a cause-and-effect link."},"",{"choice":"soon","category":"adverb of time","reason":"This word describes when something happens in time. It does not explain why something happened or what the consequence was."},{"choice":"opposite","category":"comparison of contrast","reason":"This word is used to show things that are different or contrary to one another, not to show that one event caused another to happen."}]},"studyAid":{"definition":"Transition words show how ideas in a paragraph are related; cause-and-effect transitions explain that one thing made another thing happen.","example":"It rained hard; as a result, the game was canceled. She studied a lot; therefore, she got an A.","strategyClue":"Ask yourself if the second part of the sentence is the outcome or result of the first part. If it is, look for a phrase that introduces an effect.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":30,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":183,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0190","version":5,"contentHash":"sha256:01d89caa2b529f0d5dec69cfa826960fdd074f7be530c2533d63a996be0e66a6","question":"Choose the transition that shows emphasis.","choices":["beyond","otherwise","especially","as an example"],"correct":2,"explanation":{"correct":"Answer: especially. This transition is used to highlight or emphasize a specific part of a larger idea, drawing the reader's attention to that particular point.","incorrect":[{"choice":"beyond","category":"preposition of location","reason":"This word describes distance or limits rather than importance. It does not help emphasize a specific point in a sentence."},{"choice":"otherwise","category":"transition of contrast","reason":"This word indicates what might happen if something else does not occur. It functions as a warning or contrast, not an emphasis."},"",{"choice":"as an example","category":"illustrative transition","reason":"This phrase introduces a specific instance to clarify a point, but it does not add the special weight or focus that an emphasis transition provides."}]},"studyAid":{"definition":"Emphasis transitions are special words used to show that a certain piece of information is more important or stands out from the rest.","example":"I like all fruit, especially apples. / He was tired, even exhausted, after the game.","strategyClue":"Ask yourself if the word makes the following information feel more important or 'special' compared to the rest of the sentence.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":37,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":190,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-combinations-q0292","version":5,"contentHash":"sha256:9a10b1a57c2627a9f5144f6bcf739363d11e1deca90000d0d610e360310143fb","question":"Choose the transition that shows a comparison. Penelope wants to be able to dance the ballerina she saw on stage.","choices":["just like","due to","because of","in spite of"],"correct":0,"explanation":{"correct":"Answer: just like. This transition is used to draw a comparison between Penelope's actions and the ballerina's performance, showing that she wants to model her skills after the professional.","incorrect":["",{"choice":"due to","category":"causation transition","reason":"This phrase shows cause, not comparison. It suggests the ballerina is the reason Penelope exists or dances, rather than showing that Penelope wants to dance in a similar way."},{"choice":"because of","category":"causation transition","reason":"This phrase explains why something happened. Using it here makes the sentence mean that the ballerina is the direct cause of Penelope's ability to dance, which doesn't match the intent of comparing styles."},{"choice":"in spite of","category":"contrast transition","reason":"This phrase is used to show a contradiction or something unexpected. It does not compare two things to show similarity."}]},"studyAid":{"definition":"Comparison transitions connect ideas to show how two things are similar or alike. They help the reader understand that one thing is being modeled after or compared to another.","example":"He runs just like his brother. She sings similarly to a bird. The cake tastes the same as the one from the bakery.","strategyClue":"Ask yourself if the sentence is trying to show how two things match, or if it is explaining why something happened. If it is about matching two things, look for a phrase that links the two ideas by their similarities.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-sentence-combinations","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":37,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":292,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
